  "성별이 모호하거나 논바이너리인 세 캐릭터를 묘사한 이미지.": "性別が曖昧で、ノンバイナリーな3つのキャラクターを描いた画像。",
  "4개의 컷으로 구성된 만화 형식.": "4つのカットで構成された漫画形式。",
  "5개의 패널이 연속적인 수직 또는 수평 형식으로 배열된 만화 스트립임.": "5つのパネルが連続した垂直または水平形式で配置された漫画ストリップである。",
  "미국 텍사스 주 댈러스에서 시작되어 본사를 두고 있는 24시간 편의점 국제 체인. 일본이 가장 큰 시장 중 하나이며, 20개국에 매장이 있음. 1991년 일본 계열사인 이토요카도가 세븐일레븐의 70%를 인수하여 세븐일레븐 재팬의 완전 자회사로 재편성됨. 2005년부터는 일본의 다각화된 소매 그룹인 세븐&아이 홀딩스가 소유하고 있음.": "アメリカ・テキサス州ダラスで始まり、本社を置く24時間営業の国際コンビニエンスストアチェーン。 日本は最大級の市場の一つで、20か国に店舗がある。 1991年、日本の子会社である伊藤洋加がセブンイレブンの70％を取得し、セブンイレブン・ジャパンの完全子会社として再編された。 2005年からは、日本の多角化された小売グループであるセブン＆アイ・ホールディングスが所有している。",
  ":/ 이모티콘과 비슷한 불만스러운 표정.": ":/ 絵文字に似た不満げな表情。",
