  "다이아몬드 기호 하나가 그려진 플레잉 카드.": "ダイヤモンドの記号が描かれたトランプ。",
  "하트 기호가 하나 그려진 트럼프 카드.": "ハートの記号が一つ描かれたトランプカード。",
  "단일 스페이드 기호를 묘사하는 플레잉 카드.": "単一のスペード記号を描くトランプ。",
  "비디오게임에서 업적이나 PlayStation의 트로피가 해금되었음을 알리는 알림. 7세대 이후 게임 콘솔에서 흔히 보인다.": "ビデオゲームでの実績やPlayStationのトロフィーが解放されたことを知らせる通知。 第7世代以降のゲーム機でよく見られる。",
