  "신체 부위 전체를 공백 덩어리로 칠해 검열하는 것.": "身体の部位全体を空白の塊で塗りつぶして検閲すること。",
  "홍채와 동공이 모두 없는 눈. 공막만 보임.": "虹彩と瞳孔が全くない目。 公幕だけが見える。",
  "빈 말풍선이 있는 그림이나 만화 컷. 다른 사람이 자신의 코멘트를 삽입할 수 있도록 이용됨.": "空の吹き出しがある絵や漫画のカット。 他の人が自分のコメントを挿入できるように利用される。",
  "감정, 이해, 초점이 부족한 표정.": "感情、理解、焦点が不足した表情。",
  "입 안이 눈에 띄게 붉거나 입가에서 피가 흘러내리는 것을 포함함.": "口内が目立って赤くなったり、口元から血が流れ出すことも含まれる。",
