  "이빨에 피가 묻어있는 상황으로, 폭력적이거나 위협적인 표현을 나타냄.": "歯に血が付いている状況で、暴力的または脅迫的な表現を示す。",
  "벽에 묻은 피.": "壁に付いた血。",
