  "보온을 위해 사용하는 커다란 천인 담요임.": "保温のために使う大きな布製のブランケットだ。",
  "정장 재킷과 비슷하지만 더 캐주얼한 재킷, 주로 교복에 사용됨.": "スーツジャケットに似ているが、よりカジュアルなジャケットで、主に制服に使用される。",
  "상처에서 피를 흘리는 행위.": "傷口から血を流す行為。",
  "머리 윗부분, 보통 머리카락에 가려진 곳에서 피가 나 이마 쪽으로 흘러내리는 상태. blood on face와 함께 쓰이는 경우가 많다.": "頭の上部、通常は髪の毛に隠れた部分から血が出て額の方に流れ落ちる状態。 「blood on face」と一緒に使われることが多い。",
  "배경과 전경, 또는 두 개의 개별 아이템이 경계선 없이 같은 색상으로 인해 서로 섞이는 그림.": "背景と前景、または2つの個別のアイテムが境界線なしに同じ色で混ざり合う絵。",
  "시력을 사용할 수 없는 캐릭터.": "視力を使えないキャラクター。",
  "시야를 가리기 위해 눈에 두르는 천임.": "視界を遮るために目に装着する布。",
  "착용하고 있는 안대를 들어 올려 그 아래의 눈(또는 눈의 부재)을 보여주는 것.": "着用しているアイマスクを持ち上げ、その下の目（または目の欠如）を見せること。",
  "눈을 가린 안대가 흘러내리거나 벗겨지는 상황.": "目を覆う眼帯がずれ落ちたり外れたりする状況。",
  "강한 바람과 낮은 가시성을 특징으로 하는 심한 겨울 눈보라. 유쾌해 보여서는 안 됨. 들어오는 눈의 각도가 약 45도 이상이거나, 이미 내린 눈을 강한 바람이 날리는 경우(지상 눈보라). 블리자드 엔터테인먼트와 혼동하지 말 것.": "強い風と低い視界を特徴とする厳しい冬の吹雪。 楽しそうに見えてはいけない。 入ってくる雪の角度が約45度以上であるか、すでに降った雪を強い風が吹かせる場合（地上の吹雪）。 ブリザード・エンターテインメントと混同しないこと。",
  "가스나 과식으로 인해 불어난 복부입니다.": "ガスや過食によって膨らんだ腹部です。",
  "팔이나 다리는 없지만 눈과 입이 있을 수 있는 점성의 비정형 생물.": "腕や脚はないが、目と口がある可能性のある粘性の非定型生物。",
  "정육면체 모양으로 만들어진 물체. 비디오 게임, 젠가 블록, 어린이 장난감 등 모든 종류의 블록에 사용할 수 있음.": "立方体の形で作られた物体。 ビデオゲーム、ジェンガブロック、子供用おもちゃなど、あらゆる種類のブロックに使用できる。",
  "싸움이나 전투 중 상대방의 공격을 막는 행위.": "戦闘や戦闘中に相手の攻撃を防ぐ行為。",
  "금발 또는 노란색 머리.": "金髪または黄色の髪。",
  "신체 조직에 영양분과 산소를 공급하는 체액, 피.": "体組織に栄養素と酸素を供給する体液、血液。",
  "수술 중 많은 혈액 손실이나 중상으로 인한 출혈 시 환자의 혈액을 대체하기 위해 환자나 헌혈자로부터 수집된 혈액으로 가득 찬 작은 가방.": "手術中に多くの血液損失や重傷による出血時に患者の血液を代替するために、患者や献血者から収集された血液で満たされた小さなバッグ。",
  "피가 한 방울씩 떨어지는 모습.": "血が一滴ずつ落ちる様子。",
