  "피로 만들어진 후광.": "血で作られた後光。",
  "눈의 흰자위(공막)가 자극을 받아 붉게 보이는 눈.": "目の白目（強膜）が刺激されて赤く見える目。",
  "피로 물든 날개.": "血に染まった翼。",
  "밝은 빛이 주변 영역으로 번져 보이는 시각 기술.": "明るい光が周囲の領域に広がって見える視覚技術。",
  "여성용 반바지 형태의 속옷인 블루머임.": "女性用ショートパンツ型の下着、ブルーマーだ。",
  "부르마를 잡아당김.": "ブルマを引っ張る。",
  "헐렁하게 입는 셔츠 형태의 여성용 상의임.": "ゆったりとしたシャツタイプの女性用トップスだ。",
  "입에서 공기를 세게 내뿜는 행위.": "口から強く空気を吹き出す行為。",
