  "다른 사람의 귀에 입김을 불어넣는 행위.": "他人の耳に息を吹きかける行為。",
  "손에 키스한 다음 받는 사람에게 키스를 '불어' 보내 애정을 표시하는 것.": "手にキスをした後、受け取る人にキスを「吹いて」送り、愛情を示すこと。",
  "캐릭터가 흡연 중 연기를 내뿜거나, 총구 등 다른 곳에서 나는 연기를 불어 날리는 것.": "キャラクターが喫煙中に煙を吐いたり、銃口など他の場所から出る煙を吹き飛ばすこと。",
  "호루라기를 부는 행위.": "ホルンを吹く行為。",
  "이미지의 바깥 테두리가 파란색인 경우.": "画像の外枠が青色の場合。",
  "파란색 눈동자.": "青い瞳。",
  "파란색을 띤 불꽃. 초자연적인 힘을 암시하는 시각적 표현으로 자주 쓰임.": "青色を帯びた炎。 超自然的な力を暗示する視覚的表現として頻繁に用いられる。",
  "파란색 꽃임.": "青い花だ。",
  "파란색 보석.": "青い宝石。",
  "파란색 머리.": "青い髪。",
  "파란색으로 칠한 손톱 또는 발톱임.": "青く塗られた爪または足の爪である。",
  "캐릭터나 물체 주위에 파란색으로 칠해진 외곽선.": "キャラクターや物体の周りに青色で塗られた外枠。",
  "푸른빛을 띠는 장미임.": "青い光を帯びたバラだ。",
  "파란색 하늘.": "青い空。",
