  "파트너의 페니스에 삽입 없이 엉덩이를 비비는 성행위.": "パートナーのペニスに挿入せずに尻をこすり合わせる性行為。",
  "옷 위로 엉덩이와 음경이 마찰하는 모습.": "服の上で尻と陰茎が摩擦している様子。",
  "셔츠나 다른 옷에 핀으로 고정하는 배지.": "シャツや他の服にピンで固定するバッジ。",
  "먹기 위해 잘라낸 케이크 조각.": "食べるために切り取ったケーキの一切れ。",
  "원신에 등장하는 창. 주로 신학이 휘두르는 모습으로 그려짐.": "原神に登場する槍。 主に神学が振るう姿として描かれている。",
  "게시물에 달력이 포함되어 있지만, 실제 게시물이 달력의 한 페이지가 아닌 경우.": "投稿にカレンダーが含まれているが、実際の投稿がカレンダーの1ページではない場合。",
  "승리의 황금 검. 세이버가 보통 들고 있는 검 중 하나. 엑스칼리버와 매우 비슷하지만 더 가늘고 화려함.": "勝利の黄金の剣。 セイバーが普段持っている剣の一つ。 エクスカリバーに非常に似ているが、より細く華やかだ。",
  "흰색, 주황색, 검은색 털이 섞인 고양이.": "白、オレンジ、黒の毛が混ざった猫。",
  "서예 작품이나 서예를 연습하는 캐릭터를 묘사하는 이미지.": "書道作品や書道を練習するキャラクターを描写した画像。",
  "서예, 수묵화 등을 쓸 때 사용하는 둥근 붓.": "書道や水墨画などを書くときに使う丸い筆。",
  "누군가를 부르거나 손을 흔들어 오게 하는 행위.": "誰かを呼んだり、手を振って呼び寄せる行為。",
  "휴대용 비디오 카메라.": "携帯用ビデオカメラ。",
  "낙타를 모티프로 한 동물 귀를 가진 캐릭터.": "ラクダをモチーフにした動物の耳を持つキャラクター。",
  "낙타 같은 특징을 가진 의인화된 여성 캐릭터이다.": "ラクダのような特徴を持つ擬人化された女性キャラクターである。",
  "아시아, 특히 일본, 중국, 한국이 원산지인 상록 관목에서 자라는 꽃.": "アジア、特に日本、中国、韓国が原産の常緑低木に生える花。",
  "꽉 끼는 하의에 드러난 여성의 외음부 윤곽.": "ぴったりとしたボトムスから見える女性の外陰部の輪郭。",
  "사진을 찍는 장치인 카메라임.": "写真を撮る装置であるカメラだ。",
  "카메라를 목에 걸고 있는 모습.": "カメラを首にかけている姿。",
  "사진 촬영 시 카메라에서 터지는 밝은 빛.": "写真撮影時にカメラから放たれる明るい光。",
  "얇은 끈이 달린 짧은 민소매 상의임.": "細い紐が付いた短いノースリーブのトップスだ。",
  "사람의 캐미솔을 들어 올렸을 때. 종종 브라나 가슴을 보여주기 위함.": "人のキャミソールを持ち上げたとき。 しばしばブラや胸を見せるため。",
  "캐미솔 상의를 당기거나 끌어내리는 행위.": "キャミソールの上着を引っ張ったり引き下ろしたりする行為。",
  "위장을 위한 보호색 또는 무늬. 주로 군복에 사용됨.": "胃を守るための保護色または模様。 主に軍服に使用される。",
  "특정 정보가 인쇄된 작고 평평한 조각. 명함, 트럼프 카드 등.": "特定の情報が印刷された小さく平らな部分。 名刺、トランプカードなど。",
  "이미지 전체가 카드처럼 보이거나 카드 자체의 이미지임.": "画像全体がカードのように見えるか、カード自体の画像である。",
  "카드를 가슴 사이에 끼고 있는 모습.": "カードを胸の間に挟んでいる様子。",
  "검지와 중지 사이에 카드를 끼고 들고 있는 모습.": "人差し指と中指の間にカードを挟んで持っている姿。",
  "캐릭터가 입에 카드를 물고 있을 때.": "キャラクターが口にカードをくわえているとき。",
  "공식 제품의 카드처럼 보이도록 스타일링된 팬아트.": "公式製品のカードのように見えるようにスタイリングされたファンアート。",
  "다양한 강도를 가진 두꺼운 종이의 총칭. '골판지 상자 건담' 밈의 기반이 된 재료임.": "様々な強度を持つ厚紙の総称。 『段ボール箱ガンダム』ミームの基礎となった素材だ。",
  "물건 운반, 숨기, 잠입, 로봇 제작 등에 사용되는 상자.": "物の運搬、隠蔽、潜入、ロボット製作などに使用される箱。",
  "앞이 트여있는 스웨터인 가디건임.": "前が開いているセーターのカーディガンだ。",
  "허리에 두른 가디건.": "ウエストに巻いたカーディガン。",
  "카디건을 들어올린 모습.": "カーディガンを持ち上げた姿。",
  "소매가 없는 가디건으로, 앞이 트인 스웨터 조끼와 비슷함.": "袖のないカーディガンで、前が開いたセーターのベストに似ている。",
  "심장 활동의 그래픽 표현.": "心臓活動のグラフィック表現。",
  "애정 어린 태도로 누군가를 부드럽게 만지거나 쓰다듬는 행위.": "愛情を込めた態度で誰かを優しく触れたり撫でたりする行為。",
  "고환을 쓰다듬거나 자극하는 행위.": "睾丸を撫でたり刺激したりする行為。",
  "원래 거친 작업 환경과 야외 활동을 위해 디자인된 헐렁한 스타일의 바지.": "元々、過酷な作業環境やアウトドア活動のためにデザインされたゆったりとしたスタイルのパンツ。",
  "카고 팬츠에서 파생된 헐렁한 반바지 스타일.": "カーゴパンツから派生したゆったりとしたショートパンツスタイル。",
  "장미와 비슷하지만 꽃잎이 주름지고 모양이 덜 뚜렷한 인기 있는 꽃.": "バラに似ているが、花びらがしわくちゃで形があまりはっきりしない人気の花。",
  "장난감 말을 타고 고정된 장소에서 빙글빙글 도는 놀이공원 기구. 회전목마.": "おもちゃの馬に乗って固定された場所でくるくる回る遊園地のアトラクション。 メリーゴーラウンド。",
  "두꺼운 직물로 만든 바닥 깔개. 보통 방 전체를 덮음.": "厚手の生地で作られた床用ラグ。 通常は部屋全体を覆う。",
  "캠프장에서 빛과 온기, 요리용 열을 제공하는 불.": "キャンプ場で光と温もり、料理用の熱を提供する火。",
  "자연 속에서 텐트를 치고 경치를 즐기는 활동.": "自然の中でテントを張り、景色を楽しむアクティビティ。",
  "음료나 음식을 담는 원통형 용기. 캔.": "飲料や食べ物を入れる円筒形の容器。缶。",
  "인공적으로 만들어진 큰 수로.": "人工的に作られた大きな水路。",
  "북쪽 천구에 위치한 황도대 별자리. 서쪽의 쌍둥이자리와 동쪽의 사자자리 사이에 있음.": "北の天球に位置する黄道帯の星座。 西側の双子座と東側の獅子座の間に位置する。",
  "여러 개의 장식용 촛대로 이루어진 세트의 전통적인 용어.": "複数の装飾用キャンドルで構成されたセットの伝統的な用語。",
  "심지에 불을 붙여 빛을 내는 밀랍 물체인 양초임.": "芯に火をつけて光を放つ蜜蝋の物体であるろうそくです。",
  "양초의 왁스.": "キャンドルのワックス。",
  "촛불이 주변 빛의 대부분을 제공하는 배경.": "ろうそくが周囲の光の大部分を提供する背景。",
  "양초를 하나 이상 고정하는 장치.": "キャンドルを1本以上固定する装置。",
