  "쟁반이나 다른 비슷한 물건(같은 캐릭터가 들고 있는)에 가슴을 올려놓아 다른 캐릭터나 시청자에게 대접하는 것처럼 보이는 자세.": "トレイや他の似たような物（同じキャラクターが持っている）に胸を乗せて、他のキャラクターや視聴者に接しているように見える姿勢。",
