  "머리 위로 무언가를 들고 운반하는 자세.": "頭の上で何かを持って運ぶ姿勢。",
  "다른 사람을 팔 등으로 지탱하는 모습.": "他人を腕などで支える姿。",
  "무언가나 누군가를 팔 아래, 몸통 옆에 끼고 운반하는 것.": "何かや誰かを腕の下、胴体の横に挟んで運ぶこと。",
  "짐을 운반하기 위해 동물이나 사람이 밀거나 끄는 바퀴 달린 운송 수단.": "荷物を運ぶために動物や人が押したり引いたりする車輪付きの輸送手段。",
