  "동일한 캐릭터가 한 장면에 둘 이상 등장하는 구도. 복제된 개체들은 완전히 동일한 모습과 복장을 하고 있음.": "同じキャラクターが1つのシーンに2人以上登場する構図。 複製された個体は全く同じ姿と服装をしている。",
  "대상을 매우 가까운 거리에서 보여주는 구도임.": "対象を非常に近い距離で示す構図である。",
