  "펼치지 않은 우산이나 양산.": "開かない傘や日傘。",
  "물건, 특히 옷을 보관하는 데 사용되는 붙박이장이나 문이 있는 방.": "物、特に服を保管するために使用されるクローゼットやドアのある部屋。",
