  "사람처럼 의인화되지 않은 동물이 사람 옷을 입고 있는 모습.": "人間のように擬人化されていない動物が人間の服を着ている姿。",
  "옷을 입은 채로 샤워하거나 목욕하는 것.": "服を着たままシャワーや入浴をすること。",
  "옷을 입은 여성과 나체의 여성이 함께 있는 이미지.": "服を着た女性と裸の女性が一緒にいる画像。",
  "여성은 옷을 입고 남성은 나체인 상황임.": "女性は服を着ていて、男性は裸の状態だ。",
