  "여성의 가슴골에 손을 넣어 물건을 찾는 듯한 모습.": "女性の胸の谷間に手を入れて物を探すような姿。",
  "말하는 것을 제한하기 위해 사람의 머리에 묶는 천.": "話すことを制限するために人の頭に結ぶ布。",
  "네모난 칼날을 가진 한 손으로 쓰는 정육점 칼.": "四角い刃を持つ片手で使う肉屋の包丁。",
  "뼈가 가운데로 갈라져 독특한 홈이 있는 턱.": "骨が中央に割れ、独特の溝がある顎。",
  "일부 여성의 대음순 사이의 얇은 틈새 모양. 속옷 라인이 그 모양을 따라갈 때도 사용됨.": "一部の女性の大陰唇の間の薄い隙間の形状。 下着のラインがその形に合わせて動くときにも使用される。",
  "손가락을 모두 말아 쥔 주먹임.": "指をすべて握りしめた拳だ。",
  "두 손을 꽉 쥔 모습임.": "両手をしっかり握っている姿だ。",
  "이를 악물고 있는 모습임.": "それを歯を食いしばっている様子だ。",
