  "여러 장의 종이를 고정하기 위해 상단에 클립이 달린 작은 판.": "複数の紙を固定するために、上部にクリップが付いた小さな板。",
  "손톱 깎기.": "爪切り。",
  "음핵귀두를 덮고 있는 성감대 조직.": "陰核亀頭を覆っている性感帯組織。",
