  "여성의 주요 성감대인 클리토리스임.": "女性の主要な性感帯であるクリトリスである。",
  "클리토리스나 주변 조직에 하는 여성 생식기 피어싱.": "クリトリスや周囲の組織に行う女性の生殖器ピアス。",
  "클리토리스 피어싱에 착용한 링.": "クリトリスピアスに装着したリング。",
