  "발톱 모양 장식이 달린 건틀릿.": "爪の形をした装飾が付いたガントレット。",
  "동물의 날카로운 발톱 또는 그런 형태의 손톱임.": "動物の鋭い爪、あるいはそのような形の爪である。",
  "무언가를 깨끗하게 만드는 행위. 캐릭터가 실제로 청소를 하고 있을 때 사용함.": "何かをきれいにする行為。 キャラクターが実際に掃除をしているときに使用する。",
  "청소용 붓이나 솔.": "掃除用のブラシやブラシ。",
