  "한 명 이상의 참가자가 옷을 입은 채로 하는 성관계임.": "1名以上の参加者が服を着たまま行う性行為である。",
  "긴 소매 옷을 허리에 묶은 모습.": "長袖の服を腰に結んだ姿。",
  "옷이 가슴 사이에 끼어있는 모습.": "服が胸の間に挟まっている様子。",
  "스커트나 드레스 같은 헐렁한 옷이 다리 사이, 특히 사타구니 주변에 끼어있는 모습.": "スカートやドレスのようなゆったりした服が脚の間、特に股間周りに挟まっている様子。",
  "상의를 완전히 벗지 않고 아래로 많이 내려 피부를 노출한 상태.": "上着を完全に脱がずに下に大きく下がり、肌を露出した状態。",
  "자신의 옷이나 다른 사람의 옷을 붙잡는 행위. 옷을 움직이려는 의도는 없음.": "自分の服や他人の服を掴む行為。 服を動かす意図はない。",
  "옷을 걸 수 있도록 사람의 어깨를 모방한 물체.": "服を掛けられるように人の肩を模倣した物体。",
  "실제로 입지 않고 옷을 몸 앞에 대어 보는 자세.": "実際に着ずに服を体の前にかぶせて見る姿勢。",
  "옷자락을 입에 물고 있는 모습.": "裾を口にくわえている姿。",
  "옷을 들어 올려 가슴이나 사타구니를 노출함.": "服を持ち上げて胸や股間を露出させる。",
  "바닥에 놓인 입지 않은 옷.": "床に置かれた着ていない服。",
  "빨래를 빨랫줄에 널 때 사용하는 집게.": "洗濯物を洗濯ロープに干すときに使うピンセット。",
  "옷을 아래로 당겨 신체를 노출하는 행위임.": "服を下に引っ張って身体を露出させる行為である。",
