  "캐릭터가 부주의나 서투름 때문에 실수를 저지르는 모습. 자기 다리에 걸려 넘어지는 것 등이 해당됨. '넌 틀렸어' 태그와는 달리, 지식 부족이 아닌 신체적 덜렁거림으로 인한 실수임.": "キャラクターが不注意や不器用さからミスを犯す様子。 自分の足に引っかかって転ぶことなどが該当する。 「君は間違っている」タグとは異なり、知識不足ではなく身体的な不器用さが原因のミスだ。",
  "캐릭터가 자신의 가슴을 움켜쥐거나 할퀴는 자세.": "キャラクターが自分の胸を掴んだり引っ掻いたりする姿勢。",
  "보온이나 멋을 위해 입는 길고 두꺼운 외투.": "保温やおしゃれのために着る長くて厚いコート。",
  "앞부분을 여며 코트처럼 생긴 맞춤형 드레스.": "前部分を開けてコートのようなカスタムドレス。",
  "코트나 외투가 들려 올려지거나 엉켜 있는 상태를 표현한다.": "コートや上着が持ち上げられたり、絡まっている状態を表現する。",
  "소매에 팔을 넣지 않고 어깨에 코트를 걸친 모습.": "袖に腕を入れず、肩にコートを掛けた姿。",
  "코트가 어깨에서 흘러내리거나 일부 벗겨진 상태.": "コートが肩からずり落ちたり、一部がはがれた状態。",
  "코트나 재킷의 뒷부분에서 허리 아래로 갈라져 내려오는 옷자락.": "コートやジャケットの後ろ部分からウエストの下にかけて広がる裾。",
  "자연적으로 둥근 돌로, 조약돌보다 크고 바위보다 작으며, 예전에 거리를 포장하는 데 사용되었음.": "自然に丸い石で、丸石より大きく岩より小さく、かつては道路の舗装に使用されていた。",
  "위협을 느끼면 목의 피부를 넓게 펼치는 여러 독사들의 총칭.": "脅威を感じると首の皮膚を広げて広がる複数の毒蛇の総称。",
  "코카콜라 컴퍼니에서 생산하는 세계적으로 유명한 탄산 청량음료.": "コカ・コーラ社が製造する、世界的に有名な炭酸飲料。",
  "발기를 유지하기 위해 혈류를 제한하는 음경 기저부의 링.": "勃起を維持するために血流を制限する陰茎底部のリング。",
  "한쪽 눈썹은 올라가고 다른 한쪽은 내려간 표정. raised eyebrow와 비슷하지만 내려간 눈썹도 함께 보인다.": "片方の眉は上がり、もう片方は下がった表情。 raised eyebrowと似ているが、下がった眉も一緒に見える。",
  "조종사가 차량을 제어하는 구역. 주로 차량의 앞쪽에 위치함.": "パイロットが車両を制御するエリア。 主に車両の前方に位置する。",
  "흔한 해충인 바퀴벌레.": "よく見かける害虫、ゴキブリ。",
  "바퀴벌레를 기반으로 한 절지동물 소녀.": "ゴキブリを基にした節足動物の少女。",
  "여러 재료를 섞어 만든 혼합주.": "さまざまな材料を混ぜて作った混合酒。",
