  "생식기를 덮는 옷을 옆으로 당겨 노출함.": "生殖器を覆う服を横に引っ張って露出させる。",
  "신체 일부를 노출시키기 위해 의도적으로 뚫은 구멍.": "体の一部を露出させるために意図的に開けた穴。",
  "하늘에 떠 있는 구름.": "空に浮かぶ雲。",
