  "주로 군체를 이루어 사는 해양 무척추동물.": "主に群体を形成して生活する海洋無脊椎動物。",
  "주로 산호와 다른 유기물로 구성된 암초.": "主にサンゴや他の有機物で構成された岩礁。",
  "줄이나 코드를 잡아당기는 모습.": "ラインやコードを引っ張る様子。",
  "팔이나 다리에 착용하여 신체의 해당 부위를 압박하는 직물 튜브. 근육 지원, 혈액 순환 개선, 통증 감소, 보온을 위해 사용됨. 팔꿈치, 팔뚝, 팔 전체, 허벅지, 무릎, 정강이, 다리 전체 등 팔이나 다리의 다른 부분을 덮기 위해 다양한 크기로 판매됨. 의료 및 스포츠 모두에서 사용됨. 압축 반바지도 압축 소매와 유사한 방식으로 작동함.": "腕や脚に装着し、体の該当部位を圧迫する布製チューブ。 筋肉サポート、血液循環の改善、痛みの軽減、保温のために使用される。 肘、前腕、腕全体、太もも、膝、すね、脚全体など、腕や脚のさまざまな部位を覆うために、さまざまなサイズで販売されている。 医療とスポーツの両方で使用される。 圧縮ショートパンツも圧縮スリーブと同様の方式で動作する。",
  "데이터를 조작하는 기계.": "データを操作する機械。",
  "컴퓨터에 문자를 입력하는 데 사용되는 주변 장치.": "コンピュータに文字を入力するために使用される周辺機器。",
  "화면상의 포인터를 제어하는 입력 장치.": "画面上のポインタを制御する入力装置。",
  "모니터, 키보드, 마우스를 제외한 컴퓨터의 대부분 부품을 담고 있는 케이스.": "モニター、キーボード、マウスを除いたコンピュータのほとんどの部品を収めているケース。",
  "칼이 숨겨진 지팡이나 치마 밑에 숨긴 총과 같이 숨겨진 무기.": "刀が隠された杖やスカートの下に隠された銃のような隠された武器。",
  "특정 과제에 집중하는 행위.": "特定の課題に集中する行為。",
  "청중 앞에서 펼쳐지는 라이브 음악 공연.": "聴衆の前で繰り広げられるライブ音楽公演。",
  "바다 달팽이가 사용하는 나선형 조개껍데기.": "海のカタツムリが使用する螺旋状の貝殻。",
  "콘크리트 벽이나 바닥 등이 두드러지게 보이는 배경.": "コンクリートの壁や床などが際立って見える背景。",
  "차가운 표면에 주변 공기보다 차가워져 작은 물방울이 맺히는 현상.": "冷たい表面が周囲の空気よりも冷たくなり、小さな水滴が付着する現象。",
  "임신이나 성병 예방을 위해 성기에 씌우는 라텍스 제품임.": "妊娠や性感染症の予防のために性器に装着するラテックス製品である。",
  "사용한 콘돔을 몸에 두른 모습.": "使用したコンドームを体に巻いた姿。",
  "콘돔 상자.": "コンドームの箱。",
  "condom wrapper in clothes로 이동 중인 태그.": "condom wrapper in clothesに移動中のタグ。",
  "콘돔을 입에 물고 있는 모습.": "コンドームを口にくわえている様子。",
  "삽입된 구멍(질, 항문 등) 안에 콘돔이 남아있는 상황.": "挿入された穴（膣、肛門など）の中にコンドームが残っている状況。",
  "페니스에 씌워진 콘돔임.": "ペニスに装着されたコンドームだ。",
  "여러 개의 개별 포장된 콘돔 패킷이 함께 묶여 있는 스트립.": "複数の個別包装されたコンドームパケットが一緒に束ねられたストリップ。",
  "콘돔이 들어있는 밀봉된 포장지.": "コンドームが入った密封された包装紙。",
  "원뿔 모양의 롤빵머리.": "円錐形のロールパンの頭。",
