  "인쇄 매체의 표지 페이지 아트임.": "印刷媒体の表紙ページのアートである。",
  "몸에 붙는 옷 위로 복근의 윤곽이 드러나는 모습.": "体にフィットする服の上から腹筋の輪郭が見える様子。",
  "딱 달라붙는 옷 아래로 항문이 보이거나 암시되는 경우.": "ぴったりとした服の下から肛門が見えたり、暗示される場合。",
  "클리토리스가 옷이나 다른 물건으로 덮여 있지만 그 모양이 드러나는 경우.": "クリトリスが服や他の物で覆われているが、その形が見える場合。",
  "옷 위로 쇄골의 윤곽이 드러나 보이는 상태.": "服の上から鎖骨の輪郭が見える状態。",
  "머리카락, 의복 등으로 캐릭터의 양쪽 눈이 모두 가려진 상태임.": "髪や服装などでキャラクターの両目がすべて隠れている状態だ。",
  "사람의 얼굴이 무언가에 의해 가려진 상태.": "人の顔が何かによって隠された状態。",
  "손이나 물건 등으로 입이 가려진 상태임.": "手や物などで口が覆われた状態。",
  "딱 붙는 옷 위로 배꼽의 윤곽이 보임.": "ぴったりした服の上からへその輪郭が見える。",
  "옷 위로 유두 윤곽이 드러남.": "服の上から乳首の輪郭が見える。",
  "옷이나 다른 물체에 가려져 보이지 않는 삽입.": "服や他の物体に隠れて見えない挿入。",
  "누군가의 음경이 옷 아래로 보이는 경우. 음경의 실제 모양이 명확하지 않으면 bulge 태그 사용.": "誰かの陰茎が服の下から見える場合。 陰茎の実際の形が明確でない場合は、bulgeタグを使用。",
  "옷 위로 피어싱의 자국이 보이는 것.": "服の上にピアスの跡が見えること。",
  "옷 아래에 고환이 감싸여 있는 모습.": "服の下に睾丸が包まれている様子。",
  "다른 캐릭터의 눈을 가리는 행위. 보통 손으로 함.": "他のキャラクターの目を覆う行為。 通常は手で行う。",
  "소의 귀나 뿔이 달린 동물 후드.": "牛の耳や角が付いた動物フード。",
