  "젖소 무늬 패턴이 있는 비키니.": "牛柄のパターンがあるビキニ。",
  "젖소 무늬 패턴이 있는 장갑.": "乳牛柄のパターンがある手袋。",
  "젖소 무늬 패턴의 사이하이 삭스.": "乳牛柄パターンのサイハイソックス。",
  "소와 같은 꼬리를 가진 캐릭터.": "牛のような尾を持つキャラクター。",
  "소나 양 같은 가축의 목에 다는 사각형 모양의 종.": "牛や羊などの家畜の首に付ける四角形の鈴。",
  "카우보이 서부 장르와 연관된 승마용 부츠.": "カウボーイ西部ジャンルに関連する乗馬用ブーツ。",
  "카우보이, 목장주 등이 쓰는 챙이 넓은 모자.": "カウボーイや牧場主などがかぶるつばの広い帽子。",
  "허벅지 위부터 얼굴까지 보이도록 프레임된 구도임.": "太ももの上から顔まで見えるようにフレームされた構図だ。",
  "웅크리고 손으로 머리를 감싸는 자세.": "うずくまって手で頭を包む姿勢。",
  "여성이 남성 위에 올라타 마주보는 성관계 체위임.": "女性が男性の上に乗り、向かい合う性交体位である。",
  "다른 머리카락과 다른 방향으로 뻗치거나 솟아오른 머리카락 한 가닥. 바보털.": "他の髪の毛とは異なる方向に伸びたり、立ち上がった髪の毛の一本。 バカ毛。",
  "집게발과 단단한 등껍질을 가진 갑각류.": "クローと硬い甲殻を持つ甲殻類。",
  "게 같은 외형 요소를 가진 여성 캐릭터. 집게, 갑각, 절지동물 소녀 요소를 포함할 수 있다.": "カニのような外見要素を持つ女性キャラクター。 クリップ、甲殻、節足動物の少女要素を含むことができる。",
  "머리 위에 게가 있는 모습.": "頭の上にカニがいる様子。",
  "물체의 표면에 갈라진 금.": "物体の表面に割れた金属。",
  "어두운 장면에서 한 줄기 빛이 있는 경우.": "暗いシーンで一筋の光がある場合。",
  "바닥이 갈라진 상태.": "床が割れた状態。",
  "캐릭터의 얼굴뿐만 아니라 몸의 여러 부분에 크림이 발라져 있는 상태.": "キャラクターの顔だけでなく、体のさまざまな部分にクリームが塗られている状態。",
  "크림이 든 음식을 먹은 후 얼굴에 약간의 크림이 묻어 있을 때.": "クリーム入りの食べ物を食べた後、顔に少しクリームがついているとき。",
  "맛을 낸 크림으로 채워진 부푼 패스트리.": "味付けされたクリームで満たされた膨らんだペストリー。",
  "도자기, 금속 또는 기타 재료로 만든 작은 주전자.": "陶器、金属、またはその他の材料で作られた小さなポット。",
  "괴물 같지 않은 상상의 동물이나 생명체임.": "怪物のようではない想像上の動物や生物である。",
  "캐릭터의 머리 위에 생물이 앉아 있는 모습.": "キャラクターの頭の上に生物が座っている様子。",
  "누군가의 어깨에 생물이 앉아 있는 모습.": "誰かの肩に生き物が座っている様子。",
  "섬뜩하거나 불편함을 주는 표정의 눈빛, 광기 어린 또는 이상한 눈 표현이다.": "ぞっとするような、または不快感を与える表情の目つき、狂気じみたまたは奇妙な目の表現である。",
  "얇게 부친 팬케이크의 일종.": "薄く焼いたパンケーキの一種。",
