  "초승달 모양이 달린 초커.": "三日月の形が付いたチョーカー。",
  "초승달 모양의 귀걸이.": "三日月形のイヤリング。",
  "초승달 모양의 얼굴 문양이나 문신.": "三日月形の顔の模様やタトゥー。",
  "초승달 모양의 머리 장식 또는 머리핀.": "三日月形のヘッドアクセサリーまたはヘアピン。",
  "초승달 모양의 모자 장식.": "三日月形の帽子の装飾。",
  "초승달 또는 그믐달.": "三日月または新月。",
  "초승달 모양이 달린 목걸이.": "三日月の形が付いたネックレス。",
  "초승달 모양의 핀.": "三日月形のピン。",
  "루비 로즈의 시그니처 무기.": "ルビー・ローズのシグネチャー武器。",
  "귀족 가문 등을 대표하는 매우 복잡하고 상세한 상징.": "貴族の家系などを代表する、非常に複雑で詳細なシンボル。",
  "시력 보조용 도구(주로 안경)의 유리가 깨진 상태.": "視力補助用具（主に眼鏡）のガラスが割れた状態。",
  "이미지 속 기기의 디스플레이 화면이 금이 가거나 손상됨.": "画像内の機器のディスプレイ画面にひびが入ったり、損傷したりしている。",
  "돌처럼 부서지기 쉬운 재질로 이루어진 것처럼 갈라진 피부.": "石のように壊れやすい素材でできているかのように割れた肌。",
  "벽에 금이 간 상태.": "壁にひびが入った状態。",
  "얇게 구워 주로 짭짤한 맛을 내는 비스킷 조각.": "薄く焼いて主に塩味を出すビスケットのかけら。",
  "관절을 조작하여 날카로운 꺾이는 소리를 내는 행위.": "関節を操作して鋭い曲がる音を出す行為。",
