  "기부금이나 종교적 헌금을 보관하는 상자.": "寄付金や宗教的献金を保管する箱。",
  "당나귀 귀 모양의 머리 장식 또는 귀 코스튬임.": "ロバの耳の形をした頭飾りまたは耳のコスチュームである。",
  "당나귀 귀를 가진 여성 캐릭터.": "ロバの耳を持つ女性キャラクター。",
  "당나귀 꼬리를 가진 캐릭터.": "ロバの尾を持つキャラクター。",
