  "문이 열리는 벽의 공간 또는 문 바로 바깥의 지붕 있는 구역.": "ドアが開く壁の空間、またはドアのすぐ外側の屋根のあるエリア。",
  "1964년부터 프리토레이에서 생산해 온 미국 브랜드의 맛을 낸 토르티야 칩.": "1964年からフリトレーで生産されているアメリカブランドの味を持つトルティーヤチップ。",
  "많은 물고기와 일부 해양 포유류의 등에 있는 평평하고 얇은 부분.": "多くの魚や一部の海洋哺乳類の背中にある平らで薄い部分。",
  "발이나 발가락을 정강이 쪽으로 위로 구부리는 동작.": "足や足指をすね側へ上に曲げる動作。",
  "코 아래에 작은 점 하나로만 묘사된 입.": "鼻の下に小さな点一つで描かれた口。",
  "점(·)으로 표현된 코임.": "点（·）で表されたコイン。",
  "점 모양의 동공.": "点の形をした瞳孔。",
  "원으로 구성된 패턴. 폴카 도트와 달리 점의 크기와 간격이 일정하지 않음.": "円で構成されたパターン。 ポルカドットとは異なり、点の大きさと間隔が一定ではない。",
  "작은 점이나 대시로 끊어진 연속선.": "小さな点やダッシュで切れた連続線。",
  "사무라이 갑옷의 구성 요소 중 하나로, 가슴 갑옷에 해당함.": "サムライの鎧の構成要素の一つで、胸の鎧に相当する。",
  "부상이나 질병으로 인해 두 개의 팔다리 일부 또는 전부를 잃은 캐릭터.": "怪我や病気のために、両腕と脚の一部または全部を失ったキャラクター。",
