  "머리카락을 양쪽으로 나누어 두 개의 롤빵 모양으로 만든 머리.": "髪を左右に分けて、二つのロールパンの形にした髪型。",
  "얼굴 살이 충분히 많아 두 번째 턱이 있는 것처럼 보이는 살찐 캐릭터임.": "顔の肉が十分に多く、二番目の顎があるかのように見える太ったキャラクターだ。",
  "두 개 이상의 이미지를 겹쳐서 표현하는 효과. 종종 한 이미지의 윤곽선 안에 다른 이미지를 프레임처럼 넣는 데 활용됨.": "2つ以上の画像を重ねて表現する効果。 しばしば、ある画像の輪郭内に別の画像をフレームのように配置するために利用される。",
  "한 캐릭터가 양손(또는 최소 2개)으로 손가락 총 자세를 취하는 것. 종종 누군가를 향하지만, 실제 총을 겨누는 것과는 다른 의미를 가짐.": "1つのキャラクターが両手（または最低2本）で指を撃つポーズをとること。 時々誰かに向けられるが、実際の銃を向けることとは異なる意味を持つ。",
  "양손으로 여우 그림자 인형을 만드는 모습.": "両手でキツネの影の人形を作っている様子。",
  "두 개의 헤일로를 가진 캐릭터임.": "二つのハローを持つキャラクターである。",
  "한 사람이 동시에 두 개의 페니스에 핸드잡을 하는 것.": "一人が同時に二つのペニスでハンドを握ること。",
  "서로 평행하게 이어진 두 개의 선으로, 옷에 = 모양을 형성함.": "互いに平行に続く二本の線で、衣服に=の形を形成する。",
  "하나 대신 두 개의 가운뎃손가락을 내미는 행위.": "一つの代わりに二つの中指を差し出す行為。",
  "한 캐릭터의 두 개 구멍이 동시에 관통되거나 한 구멍이 두 개의 물체로 관통되는 행위.": "あるキャラクターの二つの穴が同時に貫通する、あるいは一つの穴が二つの物体を貫通する行為。",
  "콘이나 그릇 위에 아이스크림 두 스쿱이 올라간 경우.": "コーンや皿の上にアイスクリームが2スクープ乗っている場合。",
  "두 개의 스트랩이 있는 슬립.": "2本のストラップが付いたスリップ。",
  "양손으로 동시에 엄지척 제스처를 하는 것.": "両手で同時に親指を立てるジェスチャー。",
