  "옷에 있는 두 줄의 세로 줄무늬.": "服にある二本の縦のストライプ。",
  "양손으로 W 모양을 만드는 것.": "両手でWの形を作ること。",
  "가운데 손잡이에 두 개의 검날이 붙은 무기.": "中央のハンドルに二つの刃が付いた武器。",
  "단추가 두 줄로 달리고 옷자락이 겹쳐지는 형태의 여밈 방식임.": "ボタンが二列に並び、裾が重なる形の留め具方式である。",
  "앞머리가 두 군데에서 뚜렷하게 갈라진 스타일임.": "前髪が二か所ではっきりと分かれたスタイルだ。",
  "글레이즈나 크림을 얹거나 속을 채운 작은 튀김 페이스트리. 고리 모양이 대표적이지만 다른 모양의 도넛도 포함한다.": "グレーズやクリームをのせたり、詰め込んだ小さな揚げペストリー。 リング型が代表的だが、他の形のドーナツも含まれている。",
  "헤어 도넛으로 머리를 말아 만든 원형 번. 오단고와 구분이 어려우면 사용하지 않으며 hair rings와도 구분한다.": "ヘアドーナツで髪を巻いて作った円形のバン。 オダンゴと区別が難しい場合は使用せず、hair ringsとも区別する。",
  "도넛을 본뜬 튜브.": "ドーナツを模したチューブ。",
  "가라테 등 일본 무술 수련용 복장. 도복.": "空手など日本の武術の修練用の服装。道着。",
  "동인지의 표지 페이지임.": "同人誌の表紙ページである。",
  "이 태그는 '평화의 비둘기'와 같이 흰색 또는 대부분 흰색인 새를 지칭함.": "このタグは「平和のハト」のように、白色またはほとんど白い鳥を指す。",
  "오리나 거위 깃털로 단열 처리된 재킷.": "アヒルやガチョウの羽毛で断熱処理されたジャケット。",
  "위에서 내려다보거나 몸을 숙여 셔츠 안쪽 가슴이 보이는 구도.": "上から見下ろしたり、体をかがめてシャツの内側の胸が見える構図。",
  "요가와 관련된 자세. 상체는 아래로, 엉덩이는 위로 향하게 구부린 자세로, 발을 약간 벌리고 손을 어깨너비로 바닥에 댄 채 목을 곧게 펴고 머리는 다리 쪽을 향함. 개가 일어난 후 스트레칭하는 모습에서 이름이 유래되었다고 함.": "ヨガに関連するポーズ。 上半身は下に、尻は上に向けた姿勢で、足を少し開き、手を肩幅に床に置き、首をまっすぐに伸ばし、頭は脚の方を向く。 犬が起きた後にストレッチする姿から名前が由来したと言われている。",
  "물, 기름, 무덤 등의 위치를 찾는 데 사용되는 Y자 또는 L자 모양의 막대.": "水、油、墓などの位置を探すために使用されるY字またはL字型の棒。",
  "자기만족적이거나, 거만하거나, 우쭐한 태도를 전달하는 얼굴 표정. '어때?'라는 의미의 칸사이 방언 '도야?'에서 유래.": "自己満足的、傲慢、または得意げな態度を表す顔の表情。'どう？'という意味の関西方言 'どう？'に由来。",
  "한 캐릭터가 다른 캐릭터에게 끌려가는 모습.": "あるキャラクターが別のキャラクターに引きずられる様子。",
  "신화에 등장하는 거대한 파충류 생물. 용.": "神話に登場する巨大な爬虫類生物。 ドラゴン。",
  "'드래곤볼' 시리즈에 등장하는 7개의 마법 구슬.": "'ドラゴンボール'シリーズに登場する7つの魔法の玉。",
  "뿔, 날개, 뱀 같은 꼬리 등 용의 특징을 가진 소년.": "角や翼、蛇のような尾など、ドラゴンの特徴を持つ少年。",
