  "용의 날개.": "竜の翼。",
  "잠자리목에 속하는 곤충. 큰 겹눈, 두 쌍의 튼튼한 투명 날개, 길쭉한 몸이 특징.": "トンボ目属の昆虫。 大きな複眼、二対の丈夫な透明な翼、細長い体が特徴。",
  "캐릭터의 등에 잠자리 날개 한 쌍이 있는 모습. Fate/Grand Order의 3차 재림 오베론이 이 특징으로 잘 알려져 있음.": "キャラクターの背中にトンボの羽が一対ある様子。 Fate/Grand Orderの第3次再臨オベロンはこの特徴でよく知られている。",
  "베르세르크의 가츠가 주로 휘두르는 거대한 검.": "ベルセルクのガッツが主に振るう巨大な剣。",
  "용의 돌이라 불리는 신비한 돌.": "龍の石と呼ばれる神秘的な石。",
