  "물이 빠져나가도록 하는 통로.": "水が排出される通路。",
  "지붕에서 물을 모으는 홈통과 배수관 시스템.": "屋根で水を集める溝と排水管システム。",
  "그랑블루 판타지의 종족. 소와 같은 뿔과 뾰족한 귀가 특징.": "グランブルー・ファンタジーの種族。 牛のような角と尖った耳が特徴。",
  "수납장 안에서 밀고 뺄 수 있는 서랍.": "収納棚の中で押し出したり取り出したりできる引き出し。",
  "그림을 그리는 모습.": "絵を描いている様子。",
  "그림이나 스케치 형태의 물체 오브젝트.": "絵やスケッチ形式のオブジェクト。",
  "활시위를 당겨 화살이나 유사한 발사체를 목표물에 발사할 준비를 하는 행위.": "弓の弦を引いて、矢や類似の発射体を目標に発射する準備をする行為。",
  "다른 사람의 얼굴에 그림을 그리거나 페인트를 바르는 행위.": "他人の顔に絵を描いたり、ペンキを塗る行為。",
  "어딘가에서 칼을 뽑는 행위.": "どこかで刀を抜く行為。",
  "컴퓨터 기반 드로잉 프로그램에 사용되는 평평한 직사각형 표면의 입력 장치.": "コンピュータベースの描画プログラムで使用される、平らな長方形の表面を持つ入力装置。",
