  "사진이나 그림 위에 낙서처럼 덧그린 뿔.": "写真や絵の上に落書きのように描かれた角。",
  "사진이나 이미지 위에 그려 넣은 꼬리 장식 효과. purikura나 얼굴 필터류의 낙서형 장식과 관련된다.": "写真や画像の上に描き込んだ尾飾り効果。 purikuraや顔フィルター類の落書き風装飾に関係している。",
  "사람의 얼굴에 가상으로 그려진 동물 수염.": "人の顔に仮想的に描かれた動物のひげ。",
  "당기면 천을 모아 조이는 끈. 후드티나 바지 허리에 사용됨.": "引くと布を集めて締める紐。 フーディやパンツのウエストに使用される。",
  "머리카락을 길고 단단한 밧줄 같은 가닥으로 꼬아 만든 헤어스타일.": "髪を長くてしっかりしたロープのような束にねじって作ったヘアスタイル。",
  "도레미 스위트와 관련된 분홍색의 덩어리 같은 물질.": "ドレミスイートに関連するピンク色の塊のような物質。",
  "캐릭터가 잠자는 동안 꾸는 꿈을 시각화한 것.": "キャラクターが眠っている間に見る夢を視覚化したもの。",
  "상의와 하의가 하나로 이어진 여성용 의복임.": "上着とズボンが一体となった女性用の衣服である。",
