  "패스트푸드점 직원을 위해 디자인된 유니폼.": "ファーストフード店のスタッフのためにデザインされたユニフォーム。",
  "통통한 것보다 더 살찐 상태.": "ぽっちゃりよりもさらに太った状態。",
