  "정상보다 높은 체중/통통함으로 인해 배에 여러 겹으로 접힌 지방층이 있는 피사체.": "正常より高い体重/ぽっちゃり感により、腹部に何層にも折り重なった脂肪層がある被写体。",
  "아버지와 딸이 함께 있는 모습.": "父と娘が一緒にいる様子。",
