  "부엌이나 욕실에서 물을 끌어오는 고정 장치.": "キッチンやバスルームで水を引き込む固定装置。",
  "허리와 엉덩이를 보호하는 판금 갑옷의 일부. 금속 치마처럼 생김.": "腰と臀部を保護する板金アーマーの一部。金属スカートのような形状。",
