  "지배적인 파트너가 여성인 BDSM 상황임.": "支配的なパートナーが女性であるBDSMの状況だ。",
  "들판이나 마당 등을 둘러싸는 장벽. 울타리.": "野原や庭などを囲む障壁。 フェンス。",
  "주로 깃털이나 모피로 만들어진 길고 얇은 푹신한 패션 액세서리.": "主に羽毛や毛皮で作られた長くて薄いふわふわのファッションアクセサリー。",
  "깃털로 만들거나 깃털로 장식된 코트나 외투.": "羽で作られた、または羽で飾られたコートやコート。",
