  "슈퍼카와 하이퍼카를 만드는 것으로 알려진 이탈리아 자동차 제조업체. 엔초 페라리가 설립했으며, 이 브랜드는 도로와 트랙 모두에서 고급 자동차 제조업체로서 오랜 역사를 가지고 있으며, 포뮬러 1 챔피언십과 르망 24시 레이스에서 여러 차례 우승했음. 페라리의 주요 경쟁 상대는 람보르기니와 포르쉐임.": "スーパーカーやハイパーカーを製造することで知られるイタリアの自動車メーカー。 エンツォ・フェラーリが設立し、このブランドは道路とサーキットの両方で高級自動車メーカーとして長い歴史を持ち、フォーミュラ1選手権やル・マン24時間レースで何度も優勝しています。 フェラーリの主な競合相手はランボルギーニとポルシェだ。",
  "족제비과에 속하는 유럽 족제비의 가축화된 형태. 털은 보통 갈색, 검은색, 흰색 또는 혼합색임. 길고 가는 몸을 가지고 있으며 평균 길이는 약 50cm(20인치)임.": "イタチ科に属するヨーロッパイタチの家畜化された形態。 毛は通常、茶色、黒、白、または混合色である。 長くて細い体を持ち、平均的な長さは約50cm（20インチ）である。",
  "페럿의 귀를 가진 캐릭터.": "フェレットの耳を持つキャラクター。",
