  "꽃다발을 들고 있는 모습임.": "花束を持っている姿だ。",
  "현악기 연주에 사용하는 활(보우)을 들고 있는 모습.": "弦楽器の演奏に使用する弓（ボウ）を持っている様子。",
  "장식용 리본 나비 모양의 보우를 들고 있는 모습.": "装飾用リボン 蝶の形をしたリボンを持っている姿。",
