  "발로 무언가를 잡고 있음. 발가락 사이에 있을 수도 있고 아닐 수도 있음. 발을 잡는 행위(holding own foot 또는 holding another's foot)와 혼동하지 말 것.": "足で何かを掴んでいる。 足の指の間にある場合もあれば、ない場合もある。 足を掴む行為（handle own foot または holding another's foot）と混同しないこと。",
