  "속이 빈 공간이나 구멍. 고체, 직물 등을 관통하는 개구부.": "中が空洞の空間や穴。 固体や織物などを貫通する開口部。",
  "벽에 뚫린 구멍이 있어서 반대편이 보이는 벽. 손상으로 인해 생기는 경우가 많다.": "壁に開いた穴があり、反対側が見える壁。 損傷によって生じることが多い。",
  "중앙에 구멍이 뚫린 동전.": "中央に穴が開いたコイン。",
