  "어둡고 텅 빈 구멍처럼 보이거나 그런 눈.": "暗くて空っぽの穴のように見える、そんな目。",
  "애니메이션 샬롯의 호시노우미 학원 학생들이 입는 교복.": "アニメ『シャーロット』の星のみ学園の生徒が着る制服。",
