  "끓는 육수 냄비에 다양한 동아시아 음식과 재료를 넣어 식탁에서 먹는 중국 유래의 요리법.": "沸騰した出汁の鍋にさまざまな東アジア料理と食材を入れ、食卓で楽しむ中国発のレシピ。",
  "의류 패턴의 일종.": "衣類パターンの一種。",
  "시간을 재는 장치.": "時間を計測する装置。",
  "주거용 건물.": "住宅用建物。",
  "5.56x45mm NATO 탄을 사용하는 선택 사격 가스 작동식 돌격소총. 일본 자위대의 표준 제식 소총.": "5.56x45mm NATO弾を使用する選択射撃ガス作動式突撃銃。 日本自衛隊の標準式典用小銃。",
  "하늘을 향해 고개를 들고 짐승처럼 울부짖는 모습.": "空に向かって頭を上げ、獣のように吠える姿。",
  "팔로 다른 사람을 감싸 안는 행위.": "腕で他の人を抱きしめる行為。",
