  "비현실적일 정도로 부자연스럽게 큰 리본.": "非現実的なほど不自然に大きなリボン。",
  "단일 재료를 끝에서 묶어 고리 모양으로 만든 크고 둥근 물체.": "単一の材料を端で結び、リング状にした大きくて丸い物体。",
  "귓불을 통과하는 고리 모양의 귀걸이임.": "耳たぶを通すリング状のイヤリングだ。",
  "후프 귀걸이를 참고하세요.": "フープイヤリングを参考にしてください。",
  "여러 개의 후프 위에 입어 퍼지게 만드는 스커트. 스타일에 따라 파딩게일/베르두가도/베르튀가댕(16-17세기), 파니에(18세기), 현대의 크리놀린 등 다른 이름으로 불릴 수 있음.": "複数のフープの上に着て広がるスカート。 スタイルによっては、パディンゲイル／ベルドゥガド／ベルチュガダン（16〜17世紀）、パニエ（18世紀）、現代のクリノリンなど、別の名称で呼ばれることもある。",
  "유제류 포유류의 발가락 끝. 두꺼운 케라틴 덮개로 강화됨.": "乳製品や哺乳類の指先。 厚いケラチンカバーで強化されている。",
