  "하늘과 땅 또는 바다가 만나는 경계선인 수평선 또는 지평선임.": "空と大地、あるいは海が交わる境界線である水平線または地平線である。",
  "사용자가 다양한 운동을 위해 몸을 들어 올리고 매달릴 수 있는 단일 수평 막대가 있는 장비.": "ユーザーがさまざまな運動のために体を持ち上げてぶら下がることができる単一の水平バーを持つ機器。",
  "수평 또는 직사각형 모양의 동공.": "水平または長方形の形の瞳孔。",
