  "음악이나 경고 목적으로 사용되는 속이 빈 관 형태의 물체.": "音楽や警告の目的で使用される中空の管状の物体。",
  "캐릭터의 뿔이나 가지진 뿔에 묶인 리본.": "キャラクターの角や枝の角に結ばれたリボン。",
  "뿔에 장식으로 착용한 꽃.": "角に飾りとして着用した花。",
  "캐릭터가 뿔을 잡히는 모습.": "キャラクターが角を掴まれる様子。",
  "캐릭터의 뿔에 착용하는 모든 종류의 액세서리임.": "キャラクターの角に装着するすべての種類のアクセサリーである。",
  "뿔에 장착하는 피어싱임.": "角に装着するピアスだ。",
  "캐릭터나 동물의 뿔 또는 가지진 뿔에 감겨 있는 리본.": "キャラクターや動物の角、または枝の角に巻かれているリボン。",
  "뿔에 장식된 고리.": "角に飾られたリング。",
  "장식용 가짜 뿔이 달린 머리 장식.": "装飾用の偽の角が付いたヘッドアクセサリー。",
  "뿔이 디자인된 헬멧의 한 종류.": "角がデザインされたヘルメットの一種。",
