  "전체가 레이스로 구성된 초커.": "全体がレースで構成されたチョーカー。",
  "레이스로 만든 칼라입니다.": "レースで作られたカラーです。",
  "전체가 레이스로 만들어진 장갑.": "全体がレースで作られた手袋。",
  "전체가 레이스로 만들어진 다리 의류.": "全体がレースで作られたレッグウェア。",
