  "한쪽 다리를 들어 다른 다리와 넓게 벌린 자세임.": "片足を上げて、もう片方の足と広く開いた姿勢。",
  "다리로 상대의 몸통을 감싸는 자세.": "足で相手の胴体を包む姿勢。",
