  "다리에 위치한 문신.": "脚にあるタトゥー。",
  "한쪽 다리를 위로 들어 올린 자세임.": "片足を上げた姿勢である。",
  "다리를 따뜻하게 유지하기 위해 아랫다리에 착용하는 두꺼운 덮개.": "脚を暖かく保つために、下腿に装着する厚手のカバー。",
  "다리에 감은 천 조각(주로 붕대).": "脚に巻かれた布片（主に包帯）。",
