  "캐릭터가 다리를 머리 뒤나 위로 넘긴 자세.": "キャラクターが脚を頭の後ろや上に回した姿勢。",
  "두 다리를 전체적으로 붙이고 있는 자세임.": "両足を全体的に合わせた姿勢である。",
  "두 다리를 모두 공중으로 들어 올린 자세임.": "両足を空中に持ち上げた姿勢である。",
  "양말이나 사이하이를 스트랩으로 고정하기 위해 다리에 착용하는 가터.": "靴下やサイハイをストラップで固定するために脚に装着するガーター。",
