  "식용 식물. 주로 샐러드나 샌드위치에 사용됨.": "食用植物。主にサラダやサンドイッチに使用される。",
  "레버를 사용하여 작동을 순환시키는 총의 한 종류. 카우보이나 서부극 테마의 작품에서 흔히 볼 수 있음.": "レバーを使用して作動を循環させる銃の一種。 カウボーイや西部劇をテーマにした作品でよく見られる。",
  "물리적 지지 없이 물체나 사람이 공중에 떠 있는 상태.": "物理的な支持なしに物体や人が空中に浮いている状態。",
  "남쪽 천구에 위치한 황도대 별자리. 서쪽의 처녀자리와 동쪽의 전갈자리 사이에 있음.": "南の天球に位置する黄道帯の星座。 西の乙女座と東の蠍座の間に位置する。",
  "독서 자료를 보관하는 장소.": "読書資料を保管する場所。",
  "차량이 주에 등록되었음을 나타내는 일련의 문자나 숫자를 표시하는 차량 부착 표지판.": "車両が州に登録されていることを示す一連の文字や数字を表示する車両標識。",
  "해골이나 시체 같은 외형을 가진 언데드 마법사. 판타지 장르의 대표적 존재로, 좀비와 달리 지능이 높고 마법을 쓸 수 있다.": "骸骨や死体のような外見を持つアンデッド魔法使い。 ファンタジージャンルの代表的な存在で、ゾンビとは異なり知能が高く、魔法を使うことができる。",
  "번개에 맞은 듯한 분지형 무늬가 피부에 새겨진 효과임.": "稲妻に当たったような分枝模様が肌に刻まれた効果である。",
  "혀로 외부 물체나 사람을 핥는 행위임.": "舌で外部の物体や人を舐める行為である。",
  "다른 사람의 뺨을 핥는 행위.": "他人の頬を舐める行為。",
