  "해변, 수영장, 워터파크 등에서 사람들의 안전을 감독하고, 물에 빠진 사람을 구조하며, 기타 응급 상황을 처리하는 사람.": "ビーチやプール、ウォーターパークなどで人々の安全を監督し、溺れた人を救助し、その他の緊急事態に対処する人。",
  "인명 구조원이 주변을 관찰하고 조난자를 발견하는 데 도움을 주기 위해 사용하는 매우 높은 의자임.": "人命救助隊が周囲を観察し、遭難者を発見する際に役立つ、非常に高い椅子である。",
