  "캐릭터가 담요를 들어올리는 모습. 보통 그 아래에 있는 것을 드러내거나 잠자리에 들기 위함.": "キャラクターが毛布を持ち上げる様子。 通常はその下にあるものを露出させたり、寝るためのもの。",
  "자신의 옷을 들어 올리는 행위임.": "自分の服を持ち上げる行為である。",
