  "빛나는 작은 입자들이 떠다니는 효과임.": "輝く小さな粒子が漂う効果である。",
  "물체 사이의 틈으로 들어오는 빛줄기. 빛살.": "物体の間の隙間から入ってくる光の筋。 光線。",
  "희미하고 부드러운 미소임.": "かすかで柔らかな微笑みだ。",
  "애매한 태그입니다. 대신 더 구체적인 태그를 사용하세요. 일회용 화학 조명: glowstick, 교통 지휘용 막대: traffic baton": "曖昧なタグです。 代わりに、より具体的なタグを使用してください。 使い捨て化学照明：glowstick、交通指揮用棒：traffic baton",
  "전등을 제어하는 데 사용되는 간단한 전기 장치. 스위치가 켜지면 회로가 닫혀 전기가 흐르고, 꺼지면 회로가 열려 전원 공급이 중단됨.": "電灯を制御するために使用されるシンプルな電気装置。 スイッチが入ると回路が閉じて電流が流れ、切ると回路が開いて電源供給が停止する。",
  "움직이는 광원이 남기는 흔적.": "動く光源が残す痕跡。",
