  "행운을 기원하며 사자 탈을 쓰고 사자의 움직임을 흉내 내는 중국 및 아시아 국가의 전통 춤.": "幸運を祈り、獅子の仮面をかぶり、獅子の動きを模倣する中国およびアジアの伝統舞踊。",
  "사자를 기반으로 한 동물 귀.": "ライオンを基にした動物の耳。",
  "사자의 특징을 가진 소녀.": "ライオンの特徴を持つ少女。",
