  "가슴에 립스틱으로 남은 자국. 보통 키스나 빨아서 생김.": "胸にリップスティックで残った跡。 普通はキスや吸うことでできる。",
  "립스틱으로 얼굴에 남은 자국. 보통 키스로 인해 생김.": "リップスティックで顔に残った跡。 通常はキスによって生じる。",
  "보통 키스를 통해 립스틱으로 다리에 남겨진 입술 모양의 자국.": "通常、キスを通じてリップスティックで足に残された唇の形の跡。",
