  "잘 발달된 남성 가슴 근육 사이의 골이 드러나는 부분 노출.": "よく発達した男性の胸筋の間の骨が見える部分の露出。",
  "가슴을 다른 가슴에 밀착시키는 행위.": "胸を別の胸に密着させる行為。",
