  "자신의 가슴 근육을 무언가에 누르는 행위.": "自分の胸の筋肉を何かに押し付ける行為。",
  "양쪽 가슴 근육을 손이나 팔로 꽉 쥐거나 누르는 모습.": "両胸の筋肉を手や腕でしっかり握ったり押したりする様子。",
  "남성의 가슴 근육.": "男性の胸の筋肉。",
  "발과 발톱의 외형을 개선하는 방법.": "足と爪の外観を改善する方法。",
  "배뇨 시 방광에서 배출되는 노란색 액체. 소변.": "排尿時に膀胱から排出される黄色い液体。 尿。",
  "누군가 소변을 봐서 의심스럽게 젖거나 노랗게 된 옷.": "誰かが尿をして、疑わしく濡れたり黄色くなった服。",
  "방광의 소변을 요도를 통해 배출하는 행위. 오줌싸기.": "膀胱の尿を尿道を通じて排出する行為。 おしっこをする。",
  "옷을 입은 채로 소변을 보는 모습.": "服を着たまま尿をする姿。",
  "들키지 않으려 무언가를 훔쳐보는 행위.": "見つからないように何かを盗み見る行為。",
  "모퉁이나 물체 뒤에서 밖을 엿보는 행위.": "角や物体の後ろから外を覗く行為。",
  "손으로 얼굴을 가렸지만 손가락 사이로 엿보는 모습.": "手で顔を隠しているが、指の間から覗き見している様子。",
  "껍질 벗기기.": "皮をむく。",
  "잃은 다리 일부를 나무 말뚝 같은 단순한 의족으로 대체한 경우. 보통 무릎 아래 하퇴를 대신한다.": "失った脚の一部を木の杭のような単純な義足に置き換えた場合。 通常は膝下の下腿を代わりに使用する。",
  "유두를 가리기 위해 붙이는 스티커. 니플패치.": "乳首を隠すために貼るステッカー。 ニップルパッチ。",
  "구운 과자류.": "焼き菓子類。",
  "파이핑 백이라고도 하며, 반고체 음식을 짜내는 데 사용하는 천이나 종이로 만든 손가방.": "パイピングバッグとも呼ばれ、半固体の食べ物を絞るために使用する布や紙で作られたハンドバッグ。",
  "컵케이크나 도넛과 같은 여러 개의 페이스트리를 운반하기 위해 고안된 상자.": "カップケーキやドーナツなど、複数のペストリーを運ぶために設計された箱。",
  "천 조각이나 다른 재료를 사용하여 구멍이나 찢어진 곳을 수선하는 것.": "布の切れ端や他の材料を使って、穴や裂け目を修復すること。",
  "여러 조각의 천을 이어붙여 만든 옷.": "複数の布片をつなぎ合わせて作られた服。",
  "여러 조각을 꿰매어 붙인 듯한 피부.": "いくつかのパーツを縫い合わせたような肌。",
  "차량 통행용이 아닌 다양한 종류의 길. 산책로, 오솔길 등.": "車両通行用ではないさまざまな種類の道。 散歩道や小道など。",
  "이미지에 패트리온 페이지 이름이 포함됨.": "画像にPatreonページの名前が含まれている。",
  "옷감에 뚜렷한 무늬가 짜여진 의류.": "生地に明確な模様が織り込まれた衣類。",
  "반복되는 패턴이 있는 모든 배경.": "繰り返しパターンのあるすべての背景。",
  "반복적인 패턴이 있는 의류.": "繰り返しのパターンがある衣類。",
  "실제 머리카락으로는 재현 불가능한 패턴이 있는 머리카락.": "実際の髪の毛では再現不可能なパターンを持つ髪の毛。",
  "패턴이 있는 다리 의류.": "パターンのあるレッグウェア。",
