  "무릅 위에 앉으라고 손으로 허벥지를 가볍게 두드리는 모습.": "膝の上に座るように手で軽く叩く姿。",
  "어깨를 보호하는 갑옷의 한 형태임.": "肩を保護する鎧の一形態である。",
  "거리, 보도 등의 표면을 형성하기 위해 배열된 돌.": "通りや歩道などの表面を形成するために配置された石。",
  "동물의 발 모양을 본뜬 장갑임.": "動物の足の形を模した手袋だ。",
