  "죽은 동물의 가죽과 털.": "死んだ動物の皮と毛。",
  "가랑이 앞뒤로 늘어뜨린 직사각형 천 장식임.": "股の前後に垂れ下がった長方形の布飾りだ。",
  "옆으로 젖혀진 골반 가리개(펠빅 커튼).": "横に倒れた骨盤カバー（フェルビックカーテン）。",
  "허리 장식 천을 들어 올리는 것.": "腰飾りの布を持ち上げること。",
  "잉크를 사용하여 글을 쓰거나 그림을 그리는 도구인 펜임.": "インクを使って文字を書いたり絵を描いたりする道具、ペンである。",
  "주머니에 펜이 있는 상황.": "ポケットにペンがある状況。",
  "얇은 안료 막대(주로 흑연)로 구성된 필기 또는 그림 도구.": "薄い顔料の棒（主にグラファイト）で構成された筆記または絵画用具。",
  "학생들이 연필, 펜, 지우개 등 작은 학용품을 보관하기 위해 사용하는 가방이나 케이스.": "学生が鉛筆、ペン、消しゴムなどの小さな文房具を収納するために使用するバッグやケース。",
  "몸에 꼭 맞는 직선적이고 폭이 좁은 드레스.": "体にぴったり合う直線的で幅の狭いドレス。",
  "가운데가 갈라지는 경우가 많은 매우 얇은 콧수염.": "中央が裂けていることが多い非常に細い口ひげ。",
  "폭이 좁고 몸에 꼭 맞는 스커트임.": "幅が狭く、体にぴったり合うスカートだ。",
  "목걸이에 매달아 중심 장식으로 삼는 보석 조각임.": "ネックレスに吊るして中心の装飾にする宝石のピースだ。",
  "펜던트가 달린 초커.": "ペンダントが付いたチョーカー。",
  "목에 펜던트처럼 착용하는 시계.": "首にペンダントのように着用する時計。",
