  "후추로 양념한 소고기와 돼지고기 소시지. 피자 토핑으로 인기가 있지만 샌드위치에도 사용될 수 있음.": "胡椒で味付けした牛肉と豚肉のソーセージ。 ピザのトッピングとして人気があるが、サンドイッチにも使用できる。",
