  "페르소나 시리즈에서 페르소나를 소환할 때 잠깐 번쩍이는 눈 연출. 치명타나 약점 공격을 암시하며 다른 작품 패러디도 흔하다.": "ペルソナシリーズでペルソナを召喚する際に、一瞬きらめく目の演出。 致命的な攻撃や弱点攻撃を暗示し、他の作品のパロディもよく見られる。",
