  "모호한 태그입니다. 사용하지 마세요. 검은 후춧가루로 만든 향신료의 경우 후추(향신료)를 참고하세요. 채소의 경우 파프리카를 참고하세요. 칠리 페퍼의 경우를 참고하세요. 치차나 유키츠카이 슈가의 페퍼 캐릭터의 경우 페퍼(치차나_유키츠카이_슈가)를 참고하세요.": "曖昧なタグです。 使用しないでください。 黒胡椒で作ったスパイスの場合は、胡椒（スパイス）を参考にしてください。 野菜についてはパプリカを参考にしてください。 チリペッパーの例を参考にしてください。 チチャナ・ユキツカイ・シュガーのペッパーキャラクターについては、ペッパー（チチャナ_ユキツカイ_シュガー）を参考にしてください。",
