  "아마네 카나타의 공식 상품으로, '비싸기만 한 넝마'라는 밈적 지위를 얻은 티셔츠임.": "アマネカナタの公式商品で、『高価なだけのぼろ布』というミーム的な地位を得たTシャツだ。",
  "PPSh-41은 2차 세계대전 중 소련군이 사용한 7.62×25mm 기관단총임. 1941년 중반 게오르기 슈파긴이 이전 PPD-40의 저비용, 단순화된 대안으로 개발했으며 같은 해에 실전 배치됨. 이 무기는 보통 71발 드럼 탄창과 함께 묘사되지만, 35발 곡선형 박스 탄창도 널리 사용되었음.": "PPSh-41は第二次世界大戦中にソ連軍が使用した7.62×25mm機関銃である。 1941年中頃、ゲオルギー・シュパギンが旧PPD-40の低コストで簡素化された代替として開発し、同年に実戦配備された。 この武器は通常71発のドラムマガジンと共に描かれますが、35発の曲線型ボックスマガジンも広く使用されていました。",
  "촉수처럼 의지에 따라 수축 및/또는 침투가 가능한 긴 혀. 이를 통해 손 대신 혀로 물체를 잡을 수 있음.": "触手のように意志に応じて収縮および/または侵入が可能な長い舌。 これにより、手の代わりに舌で物体を掴むことができる。",
  "파트너와의 성관계를 위해 준비된 자세를 취하는 것임.": "パートナーとの性行為のために準備された姿勢を取ることだ。",
  "한 캐릭터가 다른 캐릭터의 몸을 성관계를 준비된 자세로 잡고 있는 것. 파트너를 향해 엉덩이를 내밀거나, 다리를 벌리고 눕는 등의 자세.": "あるキャラクターが別のキャラクターの体を性行為の準備された姿勢で掴んでいること。 パートナーに向かってお尻を突き出したり、足を広げて寝る姿勢。",
  "의도적으로 암시적이거나 외설적인 방식으로 겨드랑이를 보여주는 자세.": "意図的に暗示的または猥褻な方法で脇を見せる姿勢。",
  "의도적으로 암시적이거나 음란한 방식으로 보는 사람에게 발을 내미는 행위.": "意図的に暗示的または猥褻な方法で見る人に足を差し出す行為。",
  "의도적으로 자신의 성기를 보여주는 행위.": "意図的に自分の性器を見せる行為。",
  "벗은 팬티를 보는 사람에게 보여주는 모습.": "裸のパンツを見ている人に見せる姿。",
