  "독특한 매듭 모양 또는 막대 모양의 구운 스낵.": "独特な結び目や棒状の焼きスナック。",
  "제품의 가격을 표시하기 위해 부착된 꼬리표나 스티커.": "製品の価格を表示するために貼付されたタグやステッカー。",
  "종교 의식을 집전할 권위나 권한을 가진 사람.": "宗教儀式を執り行う権威や権限を持つ人。",
  "원신에서 주로 사용되는 주요 통화 중 하나로, 게임의 가챠를 돌리는 데 주로 사용됨.": "原神で主に使用される主要通貨の一つで、ゲームのガチャを回す際に主に使われる。",
