  "모드레드(수영복 라이더)의 서핑보드. 아르토리아 펜드래건의 금고에서 '빌려온' 것. 원래 형태는 마법 방패/보트.": "モードレッド（水着ライダー）のサーフボード。 アルトリア・ペンドラゴンの金庫から「借りた」もの。元の形は魔法の盾/ボート。",
  "염력이나 초능력으로 물체나 사람을 조종하는 모습.": "念力や超能力で物体や人を操る様子。",
