  "우유를 기반으로 한 달콤한 디저트. 일본에서는 푸딩이라고 불리는 커스터드 푸딩이 일반적임.": "牛乳をベースにした甘いデザート。 日本ではプリンと呼ばれるカスタードプリンが一般的だ。",
  "표면에 고인 작은 물웅덩이.": "表面にたまった小さな水たまり。",
