  "발사체의 비행 경로를 남기거나 나타내는 가시적인 흔적. 가장 흔한 예는 과속하는 총알의 빛나는 흔적으로, 실제로는 예광탄을 발사하여 만들어짐. 이는 어떤 형태의 발사체(예: 화살, 투척 단검)에도 적용되며, 스피드 라인의 하위 집합으로 렌더링될 수 있음.": "発射体の飛行経路を残したり示したりする可視的な痕跡。最も一般的な例は、速度違反の弾丸の光る痕跡で、実際にはフラッシュバンを発射して作られる。 これは、矢や投擲短剣など、あらゆる形態の発射体に適用でき、スピードラインのサブセットとしてレンダリングされることがある。",
