  "캐릭터가 계단에 앉아 있는 모습.": "キャラクターが階段に座っている様子。",
  "캐릭터가 테이블에 앉아 있는 모습.": "キャラクターがテーブルに座っている様子。",
  "나무 그루터기에 앉아있는 자세.": "木の切り株に座っている姿。",
  "담장이나 벽 위에 앉아 있는 자세.": "塀や壁の上に座っている姿勢。",
  "물 위에 앉아있는 모습.": "水の上に座っている様子。",
  "의자나 다른 가구의 한쪽으로 다리를 모아 옆으로 앉은 자세.": "椅子や他の家具の片側に足を寄せて横に座る姿勢。",
  "16분음표.": "16分音符。",
  "두 명 이상의 인물 간의 크기 차이를 강조하는 이미지임.": "二人以上の人物間のサイズ差を強調した画像である。",
  "양 끝에 두 개의 작은 바퀴가 달린 짧고 좁은 판.": "両端に2つの小さな車輪が付いた短くて狭い板。",
  "스케이트보드를 타는 행위.": "スケートボードに乗る行為。",
  "밑창에 바퀴나 날이 부착된 부츠 한 쌍으로 이루어진 스포츠 장비.": "ソールに車輪や刃が付いたブーツのペアで構成されたスポーツ用品。",
  "롤러스케이트나 아이스 스케이트를 이용해 얼음 위나 밖에서 스케이트를 타는 것.": "ローラースケートやアイススケートを使って氷の上や外でスケートをすること。",
  "주로 뼈로 이루어진 꼬리.": "主に骨でできた尾。",
  "뼈로 만들어진 날개.": "骨で作られた翼。",
  "주 피사체는 완성되었지만 배경이 명확하게 미완성인 이미지.": "主な被写体は完成しているが、背景が明確に未完成の画像。",
  "그림을 그릴 수 있는 빈 페이지로 채워진 책.": "絵を描くことができる空白のページで埋められた本。",
  "작은 음식 조각, 특히 구운 고기나 채소를 꽂는 데 사용하는 얇은 막대.": "小さな食べ物の切れ端、特に焼き肉や野菜を刺すために使う薄い棒。",
  "스키를 타는 동안 추위, 바람, 눈, 파편 등으로부터 눈을 보호하는 데 사용되는 보호 안경.": "スキー中に寒さ、風、雪、破片などから目を保護するために使用される保護眼鏡。",
  "한쪽 다리에만 양말을 신은 캐릭터.": "片方の足だけに靴下を履いたキャラクター。",
  "한쪽 어깨만 덮는 끈이 하나만 있는 상의.": "片方の肩だけを覆うストラップが一つだけのトップス。",
  "줄무늬가 하나만 있는 의류나 물건.": "縞模様が一つだけの衣類や物。",
  "눈물 한 방울을 흘리는 것.": "涙の一滴を流すこと。",
  "한쪽 다리에만 사이 부츠를 신고, 다른 쪽 다리는 신발을 신지 않거나 다른 길이의 신발을 신은 경우.": "片方の足だけサイドブーツを履き、もう片方の足は靴を履かない、または別の長さの靴を履いている場合。",
  "한쪽 다리에만 싸이하이 삭스를 신은 모습임.": "片足だけにサイハイソックスを履いている姿だ。",
  "한 개의 이빨만 보여지는 특징적인 표정이나 모습.": "一本の歯だけが見える特徴的な表情や姿。",
  "한쪽 팔에만 팔 보호대를 착용한 캐릭터.": "片方の腕だけに腕用プロテクターを装着したキャラクター。",
  "몸에 꼭 맞는 옷에 있는 단일 세로 줄무늬.": "体にぴったり合う服にある単一の縦ストライプ。",
  "날개가 쌍을 이루지 않고 하나만 있는 경우.": "翼が対になっておらず、1つだけある場合。",
  "한쪽 손목에만 착용한 손목 커프.": "片方の手首にだけ装着したリストカフ。",
  "카메라 뷰파인더를 통해 본 이미지가 카메라의 광학 렌즈를 통해 본 이미지와 정확히 일치하는 특정 종류의 카메라.": "カメラのビューファインダーを通して見た画像が、カメラの光学レンズを通して見た画像と正確に一致する特定の種類のカメラ。",
  "비대칭적인 대각선 모양의 네크라인을 가진 드레스.": "非対称の斜め形状のネックラインを持つドレス。",
  "비대칭적인 대각선 모양의 넥라인을 가진 셔츠로, 한쪽 어깨와 가슴 윗부분 일부를 노출함.": "非対称の斜め形状のネックラインを持つシャツで、片方の肩と胸上部の一部が露出している。",
  "아마추어 레슬링에서 자주 사용되는, 스판덱스나 나일론으로 만들어진 몸에 꼭 맞는 원피스 유니폼.": "アマチュアレスリングでよく使われる、スパンデックスやナイロンで作られた体にぴったりのワンピースユニフォーム。",
  "손이나 식기를 씻기 위한 그릇 모양의 배관 설비.": "手や食器を洗うための器の形をした配管設備。",
  "물에 잠기거나 가라앉는 상태.": "水に沈んだり、沈み込む状態。",
  "두 명 이상의 자매 관계임.": "二人以上の姉妹関係である。",
  "등을 대고 누워 상체를 앉은 자세로 들어 올렸다가 다시 눕는 운동.": "背中をつけて仰向けに寝て、上半身を座った姿勢で持ち上げてから再び仰向けになる運動。",
  "HP를 회복시키는 포켓몬 나무열매.": "HPを回復させるポケモンの木の実。",
  "의자나 바닥 등에 엉덩이를 대고 앉아있음.": "椅子や床などにお尻をつけて座っている。",
  "의자 등받이가 앞으로 오도록 거꾸로 앉아 있는 자세.": "椅子の背もたれが前に来るように逆さまに座っている姿勢。",
  "나무 가지에 앉아 있는 캐릭터.": "木の枝に座っているキャラクター。",
  "창문에 앉아 있는 것임.": "窓に座っていることだ。",
  "여행 목적이 아니더라도 동물 위에 앉아 있는 경우.": "旅行目的でなくても、動物の上に座っている場合。",
  "누군가의 팔 위에 앉아 있는 모습.": "誰かの腕の上に座っている姿。",
  "공 위에 올라앉거나 균형을 잡고 앉는 모습.": "ボールの上に座ったり、バランスを取って座る姿。",
