  "고대 이집트 엘리트들이 착용했던 넓은 칼라 또는 목걸이.": "古代エジプトのエリートたちが着用していた広いカラーまたはネックレス。",
  "사용자가 소프트웨어나 다른 기술 제품과 상호작용하는 데 필요한 다양한 요소의 시각적 레이아웃.": "ユーザーがソフトウェアや他の技術製品と相互作用するために必要なさまざまな要素の視覚的レイアウト。",
