  "경찰 및 보안 요원이 장비를 휴대하기 위해 사용하는 벨트.": "警察やセキュリティ要員が装備を携帯するために使用するベルト。",
  "가공 전선 및 기타 공공 설비를 지지하는 데 사용되는 기둥. 전봇대.": "加工された電線やその他の公共設備を支えるために使用される柱。 電柱。",
  "포켓몬스터 바이올렛의 오렌지 아카데미 교복.": "ポケモンバイオレットのオレンジアカデミーの制服。",
  "목구멍 뒤쪽에 매달려 있는 작고 살이 많은 손가락 모양의 조직.": "喉の後ろにぶら下がっている小さくて肉厚な指の形をした組織。",
  "학교 등 실내에서 신는 일본식 실내화.": "学校など室内で履く日本式の室内履き。",
  "고양이 미소(:3)와 아래로 구부러진 감은 눈으로 구성된 얼굴 표정. 보통 행복, 평온, 졸음 또는 우쭐함을 표현하는 데 사용됨.": "猫の笑顔(:3)と下に曲がった目で構成された表情。 主に幸福、平穏、眠気、または得意げさを表す際に用いられる。",
  "검지와 중지로 V자 모양을 만드는 손동작.": "人差し指と中指でV字の形を作る手の動き。",
  "팔과 손을 V자 모양으로 앞으로 모은 자세임.": "腕と手をV字型に前にまとめた姿勢。",
  "V자 손 모양을 눈 위에 대고, 손가락 사이에 눈이 보이게 하는 포즈.": "V字の手の形を目の上に置き、指の間に目が見えるポーズ。",
  "캐릭터가 자신의 머리 위로 V자 손동작을 하는 모습.": "キャラクターが自分の頭の上でV字の手の動きをしている様子。",
  "입 위에 V자 모양의 손 제스처를 하고 있는 모습.": "口の上にV字型の手のジェスチャーをしている様子。",
  "건담 및 유사한 모빌슈트의 머리에 흔히 부착되는 V자 또는 U자 모양의 장식. 안테나 기능.": "ガンダムや類似のモビルスーツの頭に一般的に付けられるV字またはU字型の装飾。 アンテナ機能。",
  "V자 모양의 넥라인을 가진 상의. 셔츠나 스웨터에서 흔히 보임.": "V字型のネックラインを持つトップス。 シャツやセーターでよく見られる。",
  "안쪽으로 기울어져 V자 모양을 이루는 눈썹.": "内側に傾いてV字型を形成する眉毛。",
  "눈 윗부분이 아래로 기울어진 V자 모양을 이루는 눈매. 코믹한 상황에서 사악하거나 무서운 느낌을 표현할 때 자주 사용됨.": "目の上部が下に傾いたV字型の目元。 コミカルな状況で、邪悪や恐ろしさを表現する際に頻繁に使われる。",
  "상체와 어깨, 승모근은 넓고 허리는 좁은 체형.": "上半身と肩、僧帽筋は広く、ウエストは狭い体型。",
  "강력한 흡입력을 이용해 집안의 먼지와 먼지를 빨아들이는 청소기.": "強力な吸引力で室内のホコリを吸い込む掃除機。",
  "질 내 삽입을 묘사함.": "膣内挿入を描写する。",
  "질에 무생물 물체를 삽입하는 행위.": "膣に無生物の物体を挿入する行為。",
  "밸런타인데이와 관련된 그림임.": "バレンタインデーに関連した絵だ。",
  "북유럽 신화에서 전투에서 죽을 자를 결정하는 여신들. 보통 무장을 하고 날개와 깃털 테마로 묘사됨.": "北欧神話における戦闘で死を決める女神たち。 通常は武装し、翼と羽根をテーマに描かれる。",
  "눈에 보이는 핏줄이 있는 손.": "目に見える血管がある手。",
