  "패널이 주로 수직 순서로 배치되는 만화입니다. 높은 이미지도 참고하세요.": "パネルが主に垂直に配置される漫画です。 高い画像も参考にしてください。",
  "기관단총이나 소총을 두 손으로 잡기 용이하게 하는 수직 막대 액세서리.": "機関銃やライフルを両手で握りやすくする垂直棒アクセサリー。",
