  "> < 눈과 :D 입을 합친, 웃는 표정을 나타내는 이모티콘.": "> < 目と :D 口を合わせた、笑顔を表す絵文字。",
  "게시물에 포옹과 키스를 뜻하는 약어 xo 또는 xoxo가 들어간 경우. xo처럼 보이는 얼굴 표정은 >o<를 사용한다.": "投稿に抱擁やキスを意味する略語xoまたはxoxoが含まれている場合。xoのように見える顔の表情は >o< を使う。",
