  "테이블에 그릴이 내장된 식당의 한 종류. 손님들이 고기를 구입하여 테이블에서 직접 구워 먹음.": "テーブルにグリルが内蔵されたレストランの一種。 客が肉を購入し、テーブルで自分で焼いて食べる。",
  "중국 차오몐에서 유래한 볶음 국수.": "中国のチャオミエンに由来する炒め麺。",
  "대나무 꼬치에 작은 닭고기 조각을 구운 것.": "竹串で小さな鶏肉の切り身を焼いたもの。",
  "악기, 오토바이 등 다양한 제품을 제조하는 일본의 대기업.": "楽器やオートバイなど、さまざまな製品を製造する日本の大企業。",
  "드래곤볼의 야무차가 전투 후 쓰러진 독특한 자세를 재현한 밈 포즈.": "ドラゴンボールのヤムチャが戦闘後に倒れた独特な姿勢を再現したミームポーズ。",
  "'아픈 귀여움'을 의미하는 야미 카와이는 도쿄 거리에서 생겨난 미학.": "'痛い可愛さ'を意味するヤミ・カワイは、東京の街で生まれた美学。",
  "사랑하는 대상에게 위험할 정도로 집착하고 폭력적인 성향을 보이는 캐릭터.": "愛する対象に危険なほど執着し、暴力的な傾向を示すキャラクター。",
  "손잡이가 없는 높고 대략 원통형인 컵. 전통적으로 일본에서 차를 마시는 데 사용됨.": "持ち手のない高くておおよそ円筒形のカップ。 伝統的に日本でお茶を飲む際に使用されてきた。",
  "여성 캐릭터 간의 낭만적 또는 성적인 상호작용.": "女性キャラクター間のロマンチックまたは性的な相互作用。",
  "유유시키에 등장하는 여고 학생들이 입는 세라복임.": "ユユシキに登場する女子高生が着るセーラ服だ。",
  "동아시아가 원산지인 향기로운 감귤류 과일로, 작은 자몽과 비슷함.": "東アジア原産の香り高い柑橘類の果実で、小さなグレープフルーツに似ている。",
  "유자를 띄워 놓은 욕조에서 목욕하는 모습.": "ユズを浮かべた浴槽で入浴している様子。",
  "국제 해상 신호기 중 하나.": "国際海上信号機の一つ。",
  "'록맨 X'와 '록맨 제로' 시리즈에서 제로의 주 무기.": "'ロックマンX'と'ロックマンゼロ'シリーズでのゼロの主な武器。",
  "트레이너와 포켓몬이 Z기술을 사용하는 데 필요한 Z파워를 모으는 팔찌.": "トレーナーとポケモンがZ技を使うために必要なZパワーを集めるブレスレット。",
  "바닥에 앉을 때 사용하는 평평한 사각형 방석.": "床に座るときに使用する平らな四角形のクッション。",
  "블리치에서 사용되는 무기. 변형 가능한 근접 무기(주로 검)임.": "ブリーチで使用される武器。 変形可能な近接武器（主に剣）である。",
  "얼룩말을 기반으로 한 동물 귀를 가진 캐릭터.": "ゼブラを基にした動物の耳を持つキャラクター。",
  "얼룩말 특징을 가진 의인화 캐릭터다.": "シマウマの特徴を持つ擬人化キャラクターだ。",
  "얼룩말 꼬리를 가진 캐릭터.": "シマウマの尾を持つキャラクター。",
  "공공장소에서의 나체나 성행위가 일상적인 활동으로 취급되는 페티시.": "公共の場での裸や性行為が日常的な活動として扱われるフェティシズム。",
  "무중력 상태.": "無重力状態。",
  "메트로이드 시리즈에서 사무스 아란이 착용하는 파란색 바디슈트.": "メトロイドシリーズでサムス・アランが着用している青いボディスーツ。",
  "스커트와 사이하이 삭스 사이의 노출된 허벅지 부분.": "スカートとサイハイソックスの間の露出した太もも部分。",
  "천의 두 가장자리를 연결하는 장치인 지퍼임.": "布の二つの縁をつなぐ装置であるジッパーである。",
  "착용자의 가슴이나 가랑이 중앙을 가로지르는 지퍼가 특징인 비키니.": "着用者の胸や股の中央を横切るジッパーが特徴のビキニ。",
  "지퍼가 달린 드레스.": "ジッパー付きのドレス。",
  "지퍼가 달린 신발.": "ジッパー付きの靴。",
  "지퍼가 달린 레오타드.": "ジッパー付きのレオタード。",
  "지퍼를 여닫기 위한 손잡이 부분임.": "ジッパーを開閉するためのハンドル部分だ。",
  "옆에 지퍼가 달린 스커트.": "横にジッパーが付いたスカート。",
  "지퍼를 올리거나 내리는 모습.": "ジッパーを上げたり下げたりする様子。",
  "태양계의 황도면에 대략적으로 해당하는 밤하늘의 '띠'. 서양 점성가들은 이를 12개의 별자리로 나눔.": "太陽系の黄道面に大まかに該当する夜空の「帯」。 西洋の占星術師はこれを12の星座に分けた。",
  "되살아난 인간 또는 동물의 시체.": "蘇った人間または動物の死体。",
  "좀비처럼 허리를 구부리고 팔을 앞으로 뻗은 자세.": "ゾンビのように腰を曲げて腕を前に伸ばした姿勢。",
  "일러스트의 일부를 확대하여 보여주는 추가 레이어.": "イラストの一部を拡大して表示する追加レイヤー。",
  "'젤다의 전설' 프랜차이즈에 등장하는 물고기 인간형 종족.": "'ゼルダの伝説'フランチャイズに登場する魚の人型種族。",
  "쫄깃한 떡 케이크가 들어간 일본 전통 새해 축하 수프.": "もちもちした餅ケーキが入った日本の伝統的な新年祝いスープ。",
  "플립플랍과 매우 유사한 납작하고 끈이 있는 일본식 샌들.": "フリップフロップに非常に似た、平らで紐のある日本式サンダル。",
  "일반적으로 수면, 코골이 또는 잠자는 동안의 조용한 호흡을 나타내는 데 사용되는 효과음.": "一般的に、睡眠中やいびき、または寝ている間の静かな呼吸を示すために使用される効果音。",
  "페니 전체를 목구멍까지 집어넣는 형태의 펠라치오.": "ペニー全体を喉まで入れる形のフェラチオ。",
  "[b]Mobile Exo-Force of Korean Army[/b]\n\nA small [[mecha]], originally used as drones. The learning capabilities of their omnic foes caused the Korean Army to start recruiting gaming prodigies like [[d.va (overwatch)|Hana Song/D.Va]].\n\nh5. MEKA names (pilot)\n\n* Tokki (D.Va)\n* La Princesse Sereine (Casino)\n* Beast (D.Mon)\n* 신기전 / Singijeon (King)\n* Mastermind (Overlord)": "[b]Mobile Exo-Force of Korean Army[/b]\r\n\r\nA small [[mecha]], originally used as drones. The learning capabilities of their omnic foes caused the Korean Army to start recruiting gaming prodigies like [[d.va (overwatch)|Hana Song/D.Va]].\r\n\r\nh5。 MEKA names (pilot)\r\n\r\n*トッキ(D.Va)\r\n* La Princesse Sereine (カジノ)\r\n*ビースト(D.Mon)\r\n*新機戦/シンギジェオン(キング)\r\n* Mastermind (Overlord)",
