  "가져오기 대신 허깅페이스에서 다운로드": "インポートの代わりにハギングフェイスからダウンロード",
  "(조건)": "(条件)",
  "이전 NAIA2.0 설치(구버전 앱 또는 소스 체크아웃)의 설정·프리셋·와일드카드·태그 데이터를 현재 폴더로 복사합니다. 원본은 변경되지 않으며, 가져온 뒤": "以前のNAIA2.0インストール（旧バージョンアプリまたはソースチェックアウト）の設定・プリセット・ワイルドカード・タグデータを現在のフォルダにコピーします。オリジナルは変更されず、インポート後",
  "예를 들어": "例えば",
  "“이 태그가 있으면 저 태그를 붙여라” 같은 규칙을 만들어, 생성 직전에 프롬프트를 자동으로 손보는 기능입니다.\n규칙은 한 줄에 하나씩 씁니다.": "「このタグがあればそのタグをつけろ」などのルールを生成し、生成直前にプロンプ​​トを自動的に手書きする機能です。\nルールは1行に1つずつ書き込みます。",
