  "편집기가 대신 잡아줍니다": "エディタが代わりにキャッチ",
  "영구 토큰은 비밀번호처럼 취급하세요. 다른 사람에게 보내거나 공개된 채팅, 문서, 화면 공유에 노출하지 않는 것이 안전합니다.": "永久トークンはパスワードのように扱ってください。他人に送信したり、公開されたチャット、ドキュメント、画面共有にさらさないでください。",
  "NAIA에서 NovelAI를 사용하려면 NovelAI 계정의 영구 API 토큰이 필요합니다.\n아래 순서대로 토큰을 복사한 뒤 NAIA의 API 설정 창에 붙여넣고 저장하세요.": "NAIAでNovelAIを使用するには、NovelAIアカウントの永続APIトークンが必要です。\n以下の順序でトークンをコピーし、NAIAのAPI設定ウィンドウに貼り付けて保存します。",
  "영구 API 토큰 발급 창을 엽니다": "永続APIトークン発行ウィンドウを開きます",
  "계정 화면의 아래쪽에서": "アカウント画面の下部から",
  "이 문서는 NAIA 로컬 서버에서 제공됩니다. 문법이 바뀌면 편집기의 Syntax Guide 와 이 문서가 함께 갱신됩니다.": "この文書はNAIAローカルサーバーで提供されています。文法が変わると、エディタのSyntax Guideとこのドキュメントが一緒に更新されます。",
  "NovelAI 이미지 페이지에서 메뉴를 엽니다": "NovelAI画像ページでメニューを開きます",
  "로 표시됩니다.\n규칙을 막지는 않으니, 기존 규칙이 갑자기 동작을 멈추는 일은 없습니다.": "と表示されます。\nルールをブロックしないので、既存のルールが突然動作を停止することはありません。",
  "에 로그인한 뒤, 오른쪽 위의 메뉴 버튼을 누릅니다.": "にログインしたら、右上のメニューボタンを押します。",
  "확인 후 저장": "確認して保存",
  "영구 토큰": "永続トークン",
  "을 누릅니다.": "を押します。",
  "버튼을 누릅니다.\n현재 구독 등급이 표시되는 계정 화면에서 찾을 수 있습니다.": "ボタンを押します。\n現在、定期購入の評価が表示されているアカウント画面にあります。",
  "토큰 창이 열리면 복사 버튼을 누릅니다. 토큰 전체를 직접 펼쳐 볼 필요는 없습니다.": "トークンウィンドウが開いたら、コピーボタンを押します。トークン全体を直接展開する必要はありません。",
  "토큰을 복사합니다": "トークンをコピーします",
