  "다운로드 취소": "ダウンロードをキャンセル",
  "최신 버전을 확인하는 중입니다.": "最新バージョンを確認しています。",
  "다운로드": "ダウンロード",
  "설치하고 재시작": "インストールして再起動",
  "릴리스 페이지 열기": "リリースページを開く",
  "업데이트 확인": "アップデートの確認",
  "ⓘ 가이드": "ⓘガイド",
  "가 발생할 수 있습니다. 이 때문에": "が発生する可能性があります。このため",
  "우클릭 → 변형(I2I)·영상(I2V)": "右クリック→変形（I2I）・映像（I2V）",
  "자동화(Automation)는 제공하지 않으며": "自動化は提供されません。",
  "어떠한 책임도 지지 않습니다": "いかなる責任も負いません",
  "을 누르면 브라우저가 열립니다. 본인 xAI/SuperGrok 계정으로 로그인하면 자동으로 연결됩니다. 결과/외부 이미지를": "を押すとブラウザが開きます。自分のxAI/SuperGrokアカウントでログインすると自動的に接続されます。結果/外部画像",
  "Auto Gen 상태에서 태그 소진시 자동 중단": "Auto Genの状態でタグが消耗したときに自動停止",
