  "NovelAI 생성 시 generate-image-stream(SSE)을 사용해 생성 중간 단계 이미지를 메인 뷰어에 실시간으로 표시합니다. NAI 모드 + 기본 생성(txt2img)에서만 동작하며 Anlas 소모량은 동일합니다.": "NovelAIを生成するときは、generate-image-stream（SSE）を使用して生成中間ステップ画像をメインビューアにリアルタイムで表示します。 NAIモード+基本生成（txt2img）でのみ動作し、Anlas消費量は同じです。",
  "의 폰트를 바꿉니다. 시스템에 설치된 폰트를 고르거나, 폰트 파일(otf · ttf · woff · woff2)을 직접 추가할 수 있습니다. 추가한 폰트는 서버에 보관되어 다른 기기에서도 목록에 나타나지만,": "のフォントを置き換えます。システムにインストールされているフォントを選択したり、フォントファイル（otf・ttf・woff・woff2）を直接追加したりできます。追加したフォントはサーバーに保存され、他のデバイスでもリストに表示されますが、",
