  "[2] 1장씩 저장없이 삭제": "[2] 1枚ずつ保存せずに削除",
  "자동화가 종료될 때 완료 토스트 알림을 표시합니다.": "オートメーションの終了時に完了トースト通知を表示します。",
  "횟수 모드에서 생성할 이미지 장수입니다. 도달하면 자동 생성이 멈춥니다(반복 장도 포함).": "回数モードで生成する画像の枚数です。指定数に達すると自動生成を停止します（再生成分も含みます）。",
  "이미지를 생성할 때 저장 폴더에도 자동 저장합니다.": "画像の生成時に保存フォルダにも自動保存します。",
  "같은 프롬프트로 N회 생성한 뒤 다음 프롬프트로 넘어갑니다(시드는 매번 재랜덤화되어 변주가 생깁니다).\n\n자동 생성(자동화 시작) 상태에서만 동작하며, 값은 저장되지 않고 항상 1로 시작합니다.": "同じプロンプトでN回生成してから次のプロンプトに進みます（シードは毎回ランダムに再設定され、変化が生じます）。\n\n自動生成（自動化開始）中にのみ動作します。この値は保存されず、常に1から始まります。",
  "자동화 종료 조건입니다.\n\n무제한 = 수동 정지까지 계속 / 타이머 = 지정한 시간이 지나면 종료 / 횟수 = 지정한 장수를 생성하면 종료.": "自動化の終了条件です。\n\n無制限＝手動で停止するまで継続／タイマー＝指定時間が経過すると終了／回数＝指定枚数を生成すると終了。",
  "각 생성 사이의 대기 시간(초)입니다.\n\n무작위 ±50%를 켜면 설정값의 50~150% 범위에서 흔들어 생성 간격 패턴을 깹니다.": "各生成の間の待機時間（秒）です。\n\nランダム±50%をオンにすると、設定値の50～150%の範囲で変動し、生成間隔が一定のパターンになるのを防ぎます。",
