  "캐릭터 프롬프트를 복사했습니다.": "キャラクタープロンプトをコピーしました。",
  "앞선 슬롯의 캐릭터를 그대로 물려받습니다.\n와일드카드도 같은 값이 옵니다.\n\n연결하면 원본에 &connect: … &end 가 자동으로 붙습니다. &end 를 앞으로 당기면 그만큼만 물려줍니다.": "前のスロットのキャラクターをそのまま継承します。\nワイルドカードも同じ値を引き継ぎます。\n\n接続すると、元のプロンプトに &connect: … &end が自動で付きます。&endを前に移動すると、そこまでの範囲だけを継承します。",
