  "추가 제거에 추가": "追加削除に追加",
  "e621 Auto-Boost 포함": "e621 Auto-Boostを含む",
  "묶음 문법(밑줄 개수 무관): __x__·_x_ = x 포함 / _x·__x = \" x\" 앞 단어 경계 / x_ = x 포함 / plain = 정확일치. 중간 밑줄은 공백 취급(blue_eyes = \"blue eyes\"). (~ 는 미지원=정확일치 취급)": "バンドル文法（アンダースコアの数に関係ありません）：__x__・_x_ = xを含む/ _x・__x = \"x\"前の単語境界/ x_ = xを含む/プレーン=正確な一致。中間の下線は空白の取り扱い(blue_eyes = \"blue eyes\")。 （～は未支援＝正確一致取り扱い）",
  "빈도 기반이라 사전 목록이 없습니다.\n미리보기의 제거된 태그를 클릭해 제외하거나, 추가 제거 태그를 직접 입력하세요.": "頻度ベースなので辞書リストはありません。\nプレビューの削除済みタグをクリックして除外するか、追加の削除タグを直接入力してください。",
  "빈도 기반 · 사전 목록 없음 — 미리보기의 제거된 태그를 클릭해 제외": "頻度ベース・辞書リストなし — プレビューの削除済みタグをクリックして除外",
  "사전 미로드 — 미리보기의 제거된 태그를 클릭해 제외": "プリミロード — プレビューの削除済みタグをクリックして除外",
