  "무작위 샘플을 뽑아 결과셋을 들여다보세요.": "ランダムサンプルを抜き、結果セットを覗きます。",
  "저장할 필터가 없습니다 (칩을 추가하세요)": "保存するフィルタがありません（チップを追加してください）",
  "연결이 끊겨 저장하지 못했습니다": "接続が失われて保存に失敗しました",
  "＋ 현재 뷰를 스테이징에 추가": "＋ 現在のビューをステージングに追加",
  "필터 저장: {0}": "フィルタを保存：{0}",
  "이 카테고리가 OFF여도 항상 제거": "このカテゴリがOFFであっても常に削除",
  "무작위 샘플": "ランダムサンプル",
  "심층검색": "深い検索",
  "병합 &amp; 내보내기": "マージ＆エクスポート",
  "스테이징 초기화": "ステージングの初期化",
  "병합 → 현재 뷰": "マージ→現在のビュー",
  "심층검색(Refine) — 이미 검색된 결과셋을 아카이브 재스캔 없이 반복적으로 좁히고 합치는 작업대입니다.\n\n좌측 컨트롤로 결과 내 재검색(태그·등급·토큰/ID/Score 범위)하고, 스테이징에 서로 다른 검색을 쌓아 병합(union+중복 제거)할 수 있습니다.\n\n우측에서 무작위 샘플을 들여다보거나 생성하고, 현재 결과를 메인에 할당하거나 .parquet으로 내보냅니다.\n\n표시된 행 = 현재 작업 중인 결과, 원본 행 = 좁히기 이전의 기준 결과입니다.": "詳細検索（Refine）— アーカイブを再走査せず、検索済みの結果を繰り返し絞り込み・結合する作業画面です。\n\n左側の操作欄で結果内を再検索（タグ・等級・トークン数／ID／Score範囲）し、異なる検索結果をステージングに積んで統合（和集合＋重複除去）できます。\n\n右側ではランダムサンプルの確認・生成、現在の結果のメインへの割り当て、.parquetへの出力ができます。\n\n表示行数＝現在作業中の結果、元の行数＝絞り込み前の基準となる結果です。",
  "현재 메인 검색 결과를 심층검색 원본으로 다시 불러오기": "現在のメイン検索結果を詳細検索元に戻す",
  "심층 검색 데이터 준비 중...": "詳細検索データの準備中...",
  "검색 키워드 — 포함 검색(AND). 쉼표로 구분한 태그를 모두 포함하는 결과만 남깁니다.\n\n부분일치 — 기본은 부분 문자열 매칭입니다. 예: girl → 1girl·cowgirl 도 매칭, hair → long hair 도 매칭. (_ 는 공백으로 처리)\n\n{a|b|c} — OR 그룹. 중괄호 안 태그 중 하나라도 포함하면 매칭. 그룹끼리는 AND로 결합됩니다.\n\n*tag — 정확 태그 일치. 쉼표·공백 경계로 둘러싸인 정확한 토큰만 매칭. 예: *girl 은 girl 토큰만, 1girl·cowgirl 은 제외.": "検索キーワード — 含むタグで検索（AND）。カンマ区切りのタグをすべて含む結果だけを残します。\n\n部分一致 — 既定は部分文字列での照合です。例：girlは1girl・cowgirlにも、hairはlong hairにも一致します。（_は空白として扱います。）\n\n{a|b|c} — ORグループ。波括弧内のタグを1つでも含めば一致します。グループ同士はANDで結合します。\n\n*tag — タグの完全一致。カンマ・空白の境界で区切られた正確なトークンだけに一致します。例：*girlはgirlトークンだけに一致し、1girl・cowgirlは除外します。",
  "검색 키워드": "検索キーワード",
  "제외 키워드": "除外キーワード",
  "현재 뷰 내보내기 (.parquet)": "現在のビューのエクスポート(.parquet)",
  "먼저 검색을 실행하세요": "まず検索を実行してください",
  "현재 검색 결과를 원본 행으로 설정": "現在の検索結果を元の行に設定",
  "결과 내 재검색": "結果内の再検索",
  "검색 태그...": "検索タグ...",
  "표시된 행": "表示された行",
  "캐릭터명 없는 행 제외": "キャラクター名のない行を除く",
  "캐릭터명 없는 행만 검색": "キャラクター名のない行のみ検索",
  "제외 키워드 — 제외 검색. 입력한 태그가 든 결과를 빼냅니다. 포함 검색과 문법이 다릅니다.\n\ntag — 부분일치 제외. 해당 문자열이 든 행을 모두 제외합니다. 예: abs 는 absurdres 까지 함께 제외될 수 있습니다.\n\n~tag — 정확 태그 제외. 정확한 토큰만 제외합니다(부분일치 아님). 예: ~abs 는 abs 토큰만 제외하고 absurdres 는 유지.\n\n※ 제외 칸에서는 {a|b}·*tag 문법이 동작하지 않습니다(제외는 포함 문법의 부분집합).": "除外キーワード — 入力したタグを含む結果を除外します。含むタグの検索とは構文が異なります。\n\ntag — 部分一致で除外。その文字列を含む行をすべて除外します。例：absはabsurdresも一緒に除外する場合があります。\n\n~tag — タグの完全一致で除外。正確なトークンだけを除外します（部分一致ではありません）。例：~absはabsトークンだけを除外し、absurdresは残します。\n\n※ 除外欄では{a|b}・*tag構文は使えません（除外で使える構文は含むタグの構文の一部です）。",
  "숫자 필터": "数値フィルタ",
