  "=그룹 · 쉼표=우선순위(먼저 맞는 규칙) · 미매칭→": "=グループ・コンマ=優先順位（最初に合う規則）・未一致→",
  "연결이 끊겨 카운터를 초기화하지 못했습니다.": "接続が切断され、カウンタの初期化に失敗しました。",
  "적은 경로 적용": "少ないパスを適用",
  "=포함 ·": "=含む・",
  "날짜_시간 폴더 사용 ({11}/)": "日付_時刻フォルダの使用({11}/)",
  "저장 카운터를 1로 초기화했습니다.": "保存カウンタを1に初期化しました。",
  "합칠 parquet을 아래에서 선택하세요": "合わせるparquetを以下から選択してください",
  "내보내기 — 현재 검색 결과셋을 커스텀 parquet 파일로 저장합니다. 나중에 불러오기·합치기로 재사용할 수 있습니다.": "エクスポート - 現在の検索結果セットをカスタムparquetファイルとして保存します。後で読み込み・合せで再使用できます。",
  "— 가중치(0.7::)는 자동 무시되어 매칭됩니다.": "— 重み (0.7::) は自動的に無視されマッチングされます。",
  "실행파일 저장 — 현재 결과를 실행용 parquet(naia_temp_rows)로 저장합니다. 재시작·복구 시 이 풀에서 랜덤 프롬프트가 생성됩니다.": "実行ファイルを保存 - 現在の結果を実行のためのparquet（naia_temp_rows）として保存します。再起動・復旧時にこのプールでランダムプロンプトが生成されます。",
  "불러오기 — 저장해 둔 커스텀 parquet 결과셋을 불러옵니다. 현재 검색 결과를 이 결과셋으로 대체합니다.": "読み込み - 保存したカスタムparquet結果セットを読み込みます。現在の検索結果をこの結果セットに置き換えます。",
  "검색 결과셋(parquet) 입출력 메뉴. 저장된 결과셋을 불러오거나 현재 결과에 합치고, 현재 결과를 파일로 내보내거나 실행용으로 저장합니다.": "検索結果セット（parquet）入出力メニュー。保存した結果セットを読み込み、現在の結果に合わせて、現在の結果をファイルにエクスポートするか、実行用に保存します。",
  "내보내기": "エクスポート",
  "Exclude Keyword — 제외 검색. 입력한 태그가 든 결과를 빼냅니다. 포함 검색과 문법이 다릅니다.\n\ntag — 부분일치 제외. 해당 문자열이 든 행을 모두 제외합니다. 예: abs 는 absurdres 까지 함께 제외될 수 있습니다.\n\n~tag — 정확 태그 제외. 정확한 토큰만 제외합니다(부분일치 아님). 예: ~abs 는 abs 토큰만 제외하고 absurdres 는 유지.\n\n*tag — 정확 태그 제외. ~tag 와 같습니다(둘 다 받습니다).\n\n{a|b} — OR 그룹 제외. 그 중 하나라도 든 행을 뿕니다.": "Exclude Keyword — 入力したタグを含む結果を除外します。含むタグの検索とは構文が異なります。\n\ntag — 部分一致で除外。その文字列を含む行をすべて除外します。例：absはabsurdresも一緒に除外する場合があります。\n\n~tag — タグの完全一致で除外。正確なトークンだけを除外します（部分一致ではありません）。例：~absはabsトークンだけを除外し、absurdresは残します。\n\n*tag — タグの完全一致で除外。~tagと同じです（どちらも使えます）。\n\n{a|b} — ORグループで除外。いずれか1つでも含む行を除外します。",
  "심층검색(Refine) — 이미 검색된 결과셋을 아카이브 재스캔 없이 반복적으로 좁히고 합치는 작업대를 엽니다. 결과 위에서 추가 태그·범위로 단계적으로 다듬을 수 있습니다.": "詳細検索 - 既に検索された結果セットをアーカイブの再スキャンなしで繰り返し絞り込み、統合するワークステーションを開きます。結果 上から追加タグ・範囲に段階的に整えることができます。",
  "합치기 — 저장된 parquet 결과셋을 현재 결과에 이어붙입니다(union). 두 결과셋을 합쳐 더 넓은 풀을 만들 때 사용합니다.": "結合 - 保存されたparquet結果セットを現在の結果に接続します。 2つの結果セットを組み合わせて、より広いプールを作成するために使用します。",
  "불러올 parquet을 아래에서 선택하세요": "読み込むparquetを以下から選択してください",
  "합치기": "合わせる",
  "최신 태그 데이터 설치 완료 — 검색 기간을 {0} 까지 넓혔습니다.": "最新のタグデータのインストールが完了しました - 検索期間を{0}まで広げました。",
  "복원 — 태그 필터와 범위 좁히기를 모두 해제하고, 마지막 검색 결과셋(스냅샷) 전체로 되돌립니다.": "復元 - タグフィルタと範囲絞り込みの両方を解除し、最後の検索結果セット（スナップショット）全体に戻します。",
  "최신 태그 데이터 내려받기를 시작하지 못했습니다.": "最新のタグデータのダウンロードを開始できませんでした。",
  "확인 중...": "確認中...",
  "저장된 연결 정보를 제거합니다.": "保存した接続情報を削除します。",
  "저장된 연결 정보가 없습니다.": "保存された接続情報がありません。",
  "실행파일 저장": "実行ファイルの保存",
  "받는 중...": "受信中...",
  "최신 태그 데이터 내려받기 실패.": "最新のタグデータのダウンロードに失敗しました。",
  "기간 컷오프 (Date Cutoff)": "期間カットオフ (Date Cutoff)",
  "다른 데이터를 내려받는 중입니다. 끝난 뒤 다시 눌러 주세요.": "別のデータをダウンロードしています。終わったらもう一度押してください。",
  "시퀀스 로드 실패: {0}": "シーケンスのロードに失敗しました：{0}",
  "Ratings — 포함할 콘텐츠 등급. 켜진 등급의 결과만 검색합니다.\n\nExplicit — 명확한 성적인 행위가 있는 구도.\n\nNSFW — 확실한 노출이 있고 일부 성기 노출이 포함될 수 있는 구도, 또는 성적인 행위를 암시하는 구도.\n\nSensitive — 수영복이나 속옷 같은 일반적인 노출이 있는 구도.\n\nGeneral — 그 외의 일반적인 Safe 구도.": "Ratings — 検索に含めるコンテンツ等級。オンにした等級の結果だけを検索します。\n\nExplicit — 明確な性的行為がある構図。\n\nNSFW — 明らかな露出があり、一部の性器露出を含む場合がある構図、または性的行為を示唆する構図。\n\nSensitive — 水着や下着などの一般的な露出がある構図。\n\nGeneral — その他の一般的なSafeの構図。",
  "최신 태그 데이터 설치 완료.": "最新のタグデータのインストールが完了しました。",
  "이 클라이언트에서는 설정이 차단되었습니다.": "このクライアントでは設定がブロックされました。",
  "최신 태그 데이터를 내려받는 중입니다 (275MB).": "最新のタグデータをダウンロードしています（275MB）。",
  "연결 해제됨": "接続解除",
  "이전 프레임 시드 재사용": "前のフレームシードの再利用",
  "최신 태그 데이터": "最新のタグデータ",
  "백엔드와 연결 중입니다. 잠시 후 다시 시도하세요.": "バックエンドに接続しています。しばらくしてからもう一度お試しください。",
  "이전 프레임 +1": "前のフレーム+1",
