  "새 프레임": "新しいフレーム",
  "공통 설정": "共通設定",
  "모든 프레임 앞에 붙일 고정 프롬프트": "すべてのフレームの前に貼る固定プロンプト",
  "기간 컷오프 — 태그 아카이브를 날짜 구간으로 제한합니다. 선택한 [시작–끝] 버킷만 검색해 속도를 높이고 모델 학습 컷오프에 맞춥니다.\n\n핸들을 드래그해 시작·끝 시점을 정하면 그 구간의 parquet만 스캔합니다(구간이 좁을수록 빠름).\n\n핸들에 마우스를 올리면 해당 YYYY/MM, 아래에 선택된 parquet 수가 표시됩니다. 위치는 자동 저장됩니다.": "期間カットオフ — タグアーカイブを日付の範囲で制限します。選択した［開始–終了］の区分だけを検索して高速化し、モデルの学習カットオフに合わせます。\n\nハンドルをドラッグして開始・終了時点を指定すると、その範囲のparquetだけを走査します（範囲が狭いほど高速です）。\n\nハンドルにマウスを重ねると対応するYYYY/MM、その下には選択中のparquet数が表示されます。位置は自動保存されます。",
  "연결 해제 응답 시간이 초과되었습니다. 상태를 다시 확인해주세요.": "接続解除応答がタイムアウトしました。状態をもう一度確認してください。",
  "설정 비활성화 - 로컬 접속이 필요합니다.": "設定は無効です — ローカル接続が必要です。",
  "모든 프레임 뒤에 붙일 고정 프롬프트": "すべてのフレームの後ろに貼る固定プロンプト",
  "선행 고정 프레임": "先行固定フレーム",
