  "뒤에 추가": "後ろに追加",
  "대사만 적으세요 - 따옴표는 자동으로 붙고, 모든 프롬프트의 맨 뒤에 들어갑니다": "セリフだけを書く - 引用符は自動的について、すべてのプロンプトの最後に入ります",
