  "비워두면 생성 시점의 메인 CFG Scale을 사용합니다.": "空白のままにすると、生成時点のメインCFG Scaleを使用します。",
  "현재 프롬프트를 새 Studio 프레임으로 캡처했습니다": "現在のプロンプトを新しいStudioフレームとしてキャプチャしました",
  "공통 네거티브 뒤에 추가할 프레임 전용 네거티브": "共通ネガティブの後に追加するフレーム専用ネガティブ",
